-- Give every starter draft an actionable entry route and a clear next step.
-- Preserve authenticated author changes and any version already released.

UPDATE learning_course_versions SET
  description='Prepare a shoot that reflects the brief and permissions, then give the editor checked footage and sound with a clear record.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Check the shoot before rolling","body":"A Minjerribah Screen & Media Network shoot needs a named lead, agreed location, safe brief, permitted participants and an expected delivery. Start with those details and the actual camera and audio inputs. Run a short check with the production lead before capturing. Agree where to put source files and who can take them.\n\nRead the brief and permitted shots, locations and people. Check framing, sound and recording levels with a short test. Agree a way to signal a problem and confirm which filename or slate identifies the take.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Capture a tabletop demonstration with no private subject or recognisable record. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A test recording has a clean image and distorted voice audio. What do you do first?","choices":[{"id":"a","text":"Record the scene and leave distortion for the editor to repair."},{"id":"b","text":"Use the clean image as evidence that the sound file will be usable."},{"id":"c","text":"Adjust the audio setup and test again before recording the take."}],"correct_choice_id":"c","explanation":"A short test should make both image and audio issues visible.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two takes are called by the same name. What should the shot log do?","choices":[{"id":"a","text":"Give them distinct identifiers and note the relevant sound and image differences."},{"id":"b","text":"Rename only the preferred take and discard the other identifier."},{"id":"c","text":"Leave both with the same name and ask the editor to check timestamps."}],"correct_choice_id":"a","explanation":"Distinct identifiers let the crew and editor discuss the same take.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Transfer, back up and return gear","body":"Keep original files and relevant take notes with shared identifiers. Make the agreed backup, check files open and transfer only through the authorised custody path. Give the editor sound or visual problems, use restrictions, credit needs and unrecorded shots. Return and check gear with the owner and log faults or outstanding work.\n\nKeep the checked copies, matching log, authorised recipient, gear return and gaps in the authorised record.\n\nTransfer the checked takes and backups with the permissions, exceptions and notes an editor needs. Ask the lead what would make the next shoot easier for participants.","captureNotes":"Walk through Media delivery and equipment handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the checked copies, matching log, authorised recipient, gear return and gaps using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Files have copied but the receiving editor has no take log or restrictions. What closes the handover?","choices":[{"id":"a","text":"Send a folder name and delete the redundant working records."},{"id":"b","text":"Verify the recipient’s files and deliver the matching log, permissions and known defects."}],"correct_choice_id":"b","explanation":"The operating record needs the checked copies, matching log, authorised recipient, gear return and gaps. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the checked copies, matching log, authorised recipient, gear return and gaps"},{"id":"b","text":"a transfer link with no file or permissions tracking"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-camera-sound' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Deliver a clear review cut and accessible captions with source integrity, the required editions and a way to correct them.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Assemble a review cut","body":"For Minjerribah Screen & Media Network editing, check the current brief, authorised source media and review lead before opening a cut. Confirm intended outlets, caption format, credits and any restricted material. Make an editable review copy and keep the authoritative source references with it.\n\nStart from the agreed brief and authorised files. Keep the originals, identify the revision and mark rough or restricted material for review. Verify that names and dates match the checked sources.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Capture a fictional timeline and the exported review cut filename. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cut contains an unverified date and a restricted shot. What do you send for review?","choices":[{"id":"a","text":"A labelled work-in-progress with the fact and permission issues clearly flagged."},{"id":"b","text":"The cut as the final export and a verbal note to check it later."},{"id":"c","text":"A file that removes the flags because no one outside the crew can see it yet."}],"correct_choice_id":"a","explanation":"The reviewer needs to know which details still need a decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A name is audible in the edit but captions are misspelled. What do you do?","choices":[{"id":"a","text":"Match only the spelling guessed by speech recognition."},{"id":"b","text":"Check the name against a reliable source and correct the caption timing and text."},{"id":"c","text":"Delete the name from the captions and leave the rest unchecked."}],"correct_choice_id":"b","explanation":"Captions should accurately communicate the recording and verified wording.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Archive the checked release and hand over corrections","body":"Save the final approved files and their usable source or project reference under the agreed custody. Preserve the clearance, credits, audience, release destinations and current version. Keep superseded versions identifiable and note the owner for corrections, access or withdrawal. Arrange a checked handover and retention decision with the production lead.\n\nKeep a release index, permission and correction trail and retention owner in the authorised record.\n\nAfter review, verify the correct edition and captions at each intended destination. Give the next editor the source, approvals and any unresolved caption or correction request.","captureNotes":"Walk through Filing and next release with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a release index, permission and correction trail and retention owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A withdrawn clip is found in a promotional folder after the project ends. What should the editor pass on?","choices":[{"id":"a","text":"The affected version and approved response, where it was distributed and who verifies its removal."},{"id":"b","text":"The newest project file only because the original editor is no longer responsible."}],"correct_choice_id":"a","explanation":"The operating record needs a release index, permission and correction trail and retention owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a final zip file without a rights or version record"},{"id":"b","text":"a release index, permission and correction trail and retention owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-edit-caption' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Decide whether a venue or partner contribution fits a real screening or production and agree who does what.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Work out what you can offer","body":"For a Minjerribah Screen & Media Network venue partnership, start with a particular screening or production. Compare the organisers’ request with available site access, equipment, people, rights, cost and support. Ask the project lead who can make an agreement and how it will be recorded.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Use a fictional venue discussion, with the public hosting or participation route on screen. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    '$[4]', json('{"title":"Check the site back in and pass on lessons","body":"Agree a condition check, return of keys and gear, incident or accessibility issues, feedback and any correction of public details. Keep the relevant agreement and review date so a successor knows what is still in effect.\n\nAfter the activity, check the condition of the site and equipment and agree one action to improve future access or support.","captureNotes":"Walk through Venue handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-host' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the right authority for capture, editing, release and reuse, and keep permission decisions attached to the material.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Identify the person who can decide","body":"For a Minjerribah Screen & Media Network activity, get the actual brief, intended audience and proposed material. Ask who can decide for the venue, contributors, rights owners and relevant cultural custodians. Record each permission separately with scope and review point. Hold a proposed use that has no decision-maker or unclear authority.\n\nList the material, its source, intended audiences, and who holds relevant permission. Approach the appropriate cultural custodians about cultural material. Ask for the method and scope of review they want.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Use a fictional permission register without real identities, private files or sensitive knowledge. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which combination belongs in a useful permission request?","choices":[{"id":"a","text":"Item and a request to authorise every future use by default."},{"id":"b","text":"Item, authority, audience, specific uses and how the person wants to review them."},{"id":"c","text":"Item, a publishing date and the producer''s preferred platform only."}],"correct_choice_id":"b","explanation":"Clear scope lets the right person make an informed decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two people offer conflicting instructions about cultural material. What should the team do?","choices":[{"id":"a","text":"Choose the most convenient instruction in order to finish the edit."},{"id":"b","text":"Record both as permissions and release a shorter version."},{"id":"c","text":"Hold the proposed use and seek direction from the appropriate authorised custodian."}],"correct_choice_id":"c","explanation":"Cultural authority needs to be clear before using the material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Respond to concerns and maintain custody","body":"When a concern, expiry or withdrawal arrives, identify the exact asset, approved uses, locations and responsible publisher. Ask the appropriate owner to confirm the response. Notify authorised crew, verify corrections or takedowns and update the restricted history. Pass permissions and holds by appropriate scope when the project changes hands.\n\nKeep the decision, all affected uses, verified results and custody or review date in the authorised record.\n\nConfirm the release matches the agreed scope. If someone asks for a different use or withdrawal, record and send it to the right decision-maker with the current file reference.","captureNotes":"Walk through Permission change and handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the decision, all affected uses, verified results and custody or review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A person changes permission after two outlets received the release. What should be checked?","choices":[{"id":"a","text":"Confirm the required response, affected outlets and who verifies action at each."},{"id":"b","text":"Remove one local copy and treat it as fully withdrawn."}],"correct_choice_id":"a","explanation":"The operating record needs the decision, all affected uses, verified results and custody or review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a changed master file without an outlet or audit check"},{"id":"b","text":"the decision, all affected uses, verified results and custody or review date"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-permissions' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Bring a media proposal to a clear scope, permission, delivery and financial record, then hand it over without losing context.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Set a workable scope","body":"For a Minjerribah Screen & Media Network production, start with the named project owner, purpose, audience, budget and current authority. Check whether the request is a proposal or a confirmed project. Agree who can review rights, cultural responsibilities, safeguarding, cash commitments and public release before rostering crew.\n\nWrite what the project will deliver, the audience and what can fit the available team and resources. Assign someone to confirm the venue, permissions, funding status and each public claim.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Record a fictional project card beside the public network or funding page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A venue conversation is positive and the project has a filmmaker. What does a scoped brief still need?","choices":[{"id":"a","text":"The confirmed venue status, permissions owner, crew capacity and costs to check."},{"id":"b","text":"Only a working title and an audience estimate."},{"id":"c","text":"A confirmed public date based on everyone being interested."}],"correct_choice_id":"a","explanation":"A workable production scope identifies its real dependencies.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An edit adds new audience uses that were never discussed. What should the producer do?","choices":[{"id":"a","text":"Treat the approval of the original brief as covering the new uses."},{"id":"b","text":"Ask who can approve the additional uses and record the result before release."},{"id":"c","text":"Send the new version to another channel without updating the permission notes."}],"correct_choice_id":"b","explanation":"New uses may require a new decision from the relevant people.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Close production, reporting and ownership","body":"Confirm which outputs were cleared and delivered, check partner acknowledgements, reconcile costs and grant obligations, and follow up on outstanding rights or custody. Arrange storage, archive, retention and equipment return with the responsible owners. Give the successor final versions, next deadlines and private contacts by approved reference. Verify any published correction and unresolved issue status.\n\nKeep the completion position, costs, approved outputs, custody and open tasks in the authorised record.\n\nClose with what was delivered, who may use it, what remains open and when the owner will check the result with participants or the host.","captureNotes":"Walk through Delivery, archive and handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the completion position, costs, approved outputs, custody and open tasks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A finished project has unpaid supplier costs and material awaiting rights confirmation. How do you close it?","choices":[{"id":"a","text":"Mark the project closed because the premiere and audience report are finished."},{"id":"b","text":"Record the financial and release exceptions with their authorised owners and keep them open until verified."}],"correct_choice_id":"b","explanation":"The operating record needs the completion position, costs, approved outputs, custody and open tasks. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the completion position, costs, approved outputs, custody and open tasks"},{"id":"b","text":"the distribution link and a declaration that all delivery is complete"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-producer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Develop a local story someone can independently verify and the editor can publish within the agreed boundaries.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Start with the claim and source","body":"A Minjerribah Screen & Media Network assignment needs a project lead, audience, purpose and approved approach to sources. Start with a claim or question. Agree what may be collected, quoted or published and how to verify it before interviewing or drafting. Keep a route for source corrections.\n\nList the main facts the story needs, their sources and the people who can verify disputed or unclear details. Label reconstructions and creative elements in your working brief.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Show a fictional story treatments folder with source and open-question columns. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two sources disagree on a date. What belongs in the brief?","choices":[{"id":"a","text":"The date from the newest document with no mention of the older one."},{"id":"b","text":"The two sources, marked discrepancy and intended authoritative check."},{"id":"c","text":"An average or approximate date that avoids the disagreement."}],"correct_choice_id":"b","explanation":"Open discrepancies need a way to be resolved before a factual claim is used.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A scene recreates something for which no footage exists. How should the draft describe it?","choices":[{"id":"a","text":"Treat it as documentary footage once cut with real interviews."},{"id":"b","text":"Avoid describing the source so viewers can form their own interpretation."},{"id":"c","text":"Clearly label the scene as a reconstruction or creative element."}],"correct_choice_id":"c","explanation":"The review brief needs to show what the production is reconstructing.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Prepare an editor and publisher handover","body":"Provide the editor with the current approved story outline, usable text and media, source and permission references, attribution, questions still open and what must stay out. Give the publisher the right channel and reviewed status. Agree how future corrections and archive requests will be handled.\n\nKeep the approved copy, verifiable source and permissions with an exceptions owner in the authorised record.\n\nHand the editor the facts, contested points, permissions and current edition so a correction or reuse request can be resolved with the right person.","captureNotes":"Walk through Story handover and permissions check with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the approved copy, verifiable source and permissions with an exceptions owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The editor receives a draft with removed material and no explanation. What handover would help?","choices":[{"id":"a","text":"Record the relevant use restriction and cleared version with an approved reference, without sending the private detail."},{"id":"b","text":"Send the removed material so the editor can independently decide."}],"correct_choice_id":"a","explanation":"The operating record needs the approved copy, verifiable source and permissions with an exceptions owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"an export which omits restricted notes and version status"},{"id":"b","text":"the approved copy, verifiable source and permissions with an exceptions owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-research-writer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run an accessible screening from the agreed programme to audience checks, a fallback and a useful pack-down record.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Prepare the run sheet","body":"A Minjerribah Screen & Media Network screening needs a confirmed venue, crew lead, authorised film edition and rights for the intended audience. Get the run sheet, equipment list and access plan. Check captions, sound, the audience route and who can change the session before opening doors.\n\nConfirm the screening and venue decisions with the lead. Allocate projection, sound, audience welcome, accessible seating and pack-down. Ask who can pause or change the programme.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Record a practice set-up and a fictional crew run sheet. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The run sheet lists audience welcome and AV test at the same time. What should be reviewed?","choices":[{"id":"a","text":"Whether an audience member could cover welcome if people arrive early."},{"id":"b","text":"Whether the AV test can be dropped to simplify the schedule."},{"id":"c","text":"Named crew for each duty, a backup and the timing of their checks."}],"correct_choice_id":"c","explanation":"Critical jobs need enough crew and time to be carried out.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The intended screening file has captions, but no one has checked them on the actual screen. What do you do?","choices":[{"id":"a","text":"Test the file and caption readability with the intended equipment before opening."},{"id":"b","text":"Test only whether the file launches on a laptop."},{"id":"c","text":"Leave caption checking until a viewer asks about it."}],"correct_choice_id":"a","explanation":"A playback check on the equipment verifies the actual experience.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    '$[5]', json('{"title":"Pack down, report and hand over","body":"Use the agreed safe pack-down, return all gear to named custodians and report faults and missing items. Confirm the site condition, event costs, media custody and restricted incident records through the relevant owners. Collect appropriate feedback and exercise the handover to the next screening team with review dates.\n\nKeep the equipment, custody and incident or follow-up record with owners in the authorised record.\n\nRecord what the actual audience experienced, any permission or equipment issue and the changes the next crew should test.","captureNotes":"Walk through Equipment and screening debrief with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the equipment, custody and incident or follow-up record with owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Something is damaged during pack-down and another event has booked it. What should the next team receive?","choices":[{"id":"a","text":"The booked equipment list with fault details left in someone’s text messages."},{"id":"b","text":"The asset, condition, held status, responsible repair or substitute and next check."}],"correct_choice_id":"b","explanation":"The operating record needs the equipment, custody and incident or follow-up record with owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the equipment, custody and incident or follow-up record with owners"},{"id":"b","text":"a note that the event finished, with no asset condition checks"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-screen-crew' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find a practical route to contribute a story, learn a media task, host a screening or discuss a project.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Tour the public pages","body":"The Minjerribah Screen & Media Network brings together local reporting, filmmaking, screenings and supported practice. Open the public network and choose an activity or outcome. Check which projects or venues are confirmed and who can answer a question about access, permission or taking part.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Capture the public site’s navigation and sources page using only material cleared for public viewing. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    '$[4]', json('{"title":"Choose and follow up an enquiry","body":"Choose a suitable route to offer interest and state what you can actually provide or would like to learn. Ask what permission, site or model still needs a decision. Keep personal or cultural details out of public submissions and ask for the proper route if needed.\n\nAsk about one actual opportunity or permission decision and keep the project name and current contact with the reply.","captureNotes":"Walk through Join the build with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-site-tour' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Offer a local story with a clear purpose, trusted source and permission someone else can check.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Write a first story note","body":"The Minjerribah Screen & Media Network helps develop and share local stories. Start by describing the story, who it would help and where it might appear. Ask the project editor or lead how to propose it. Check with the people involved and the relevant custodian before recording identifiable or culturally governed material.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Capture a made-up pitch card and the public Join the build page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    '$[4]', json('{"title":"Follow the story through review","body":"Check the reviewed wording, facts, credited contributions and intended audience. Give the producer the correct source and note what should be held. Ask how to report a mistake or changed permission and where any approved copy will be kept.\n\nGive the editor the current pitch, what can be used and how to reach the people who can confirm or change permission.","captureNotes":"Walk through Producer or editor contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-story-contributor' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Get a supported media task, practise with appropriate material and finish with feedback and a usable handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find a starter task","body":"The Minjerribah Screen & Media Network is a route into local media work and practice. Start with an actual project or approved rehearsal and a named lead. Ask for one task with a clear outcome, supervision, access and permitted material. Agree what evidence or result you will deliver and how the lead will give feedback.\n\nOpen the Minjerribah Screen & Media Network | https://auraofintelligence.github.io/minjerribah-screen-media-network/","captureNotes":"Show a fictional workshop list and chosen task card. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    '$[1]', json('{"title":"Agree the check-in and feedback","body":"Ask the lead to show what a good take log, caption or first draft looks like. Agree when you can ask for help and when they can check the result. A useful first assignment can be completed with the available equipment and permission. Ask about another task if the current one needs access or training you have not been offered."}'),
    '$[4]', json('{"title":"Finish with evidence and feedback","body":"Return equipment and show the output, source or file reference, what was checked and what still needs review. Agree the next skill to practise, and ask about portfolio use and credit separately. Route a workplace, privacy or welfare concern to the designated person.\n\nHand over a checked file or notes with permissions and unresolved questions. Use the feedback to choose the next role or another supervised practice.","captureNotes":"Walk through Trainee handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='msmn-trainee' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Publish a business update with accurate terms, suitable outlets, an expiry and an owner who can correct it.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose information people can act on","body":"The Straddie Noticeboard Network is for useful local notices. A business update needs an authorised publisher, an actual offer or service change and details people can rely on. Start by checking who can approve the wording, dates, conditions, public contact and intended outlets. Use the publishing workflow and the relevant reviewer or outlet agreement.\n\nCheck a public business listing or service-hours notice. State the business name, location, hours, source and end date for a temporary change. Confirm who can speak for the business.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Use the public business directory and a made-up closure or opening-hours change. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cafe will close early this Thursday only. What should the notice say?","choices":[{"id":"a","text":"The regular business hours with the temporary change in an unlabelled note."},{"id":"b","text":"The new hours as an indefinite listing until the business changes them again."},{"id":"c","text":"The affected location and date, revised hours, source and expiry."}],"correct_choice_id":"c","explanation":"A time-limited change should be specific enough for visitors to act on.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two staff members send conflicting hours. What should happen before review?","choices":[{"id":"a","text":"Ask the nominated business contact to confirm the current hours and source."},{"id":"b","text":"Use whichever set of hours matches last month''s listing."},{"id":"c","text":"Publish a range of both hours and wait for people to report an issue."}],"correct_choice_id":"a","explanation":"The business contact can resolve which information is authoritative.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Handle public questions and hand over publisher duties","body":"Answer from the verified business source and route any privacy, accessibility or complaint concern to the responsible person. Maintain the approval and expiry record for future offers, and give the successor the approved account scope, public contact, open notices and timing to review them. Keep other staff details out of the public feed.\n\nKeep the checked publisher scope, open notice IDs and correction route in the authorised record.\n\nKeep the current notice reference and expiry. Check whether visitors could misread timing or access, and send verified corrections to the relevant outlets.","captureNotes":"Walk through Business contact and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the checked publisher scope, open notice IDs and correction route using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A customer reports a wrong listing while the designated issuer is away. What should the handover provide?","choices":[{"id":"a","text":"Access to the previous publisher’s account so any staff member can edit."},{"id":"b","text":"The agreed backup and correction authority, notice reference and verification status."}],"correct_choice_id":"b","explanation":"The operating record needs the checked publisher scope, open notice IDs and correction route. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the checked publisher scope, open notice IDs and correction route"},{"id":"b","text":"an export of saved drafts with no current contact or expiry"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-business-publisher' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a useful community notice and give a reviewer the facts, source, permission and correction contact they need.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Prepare a draft","body":"The Straddie Noticeboard Network shares local information through agreed channels. Choose a notice people can use, such as a changed hall opening or a confirmed activity. Start with the actual organiser or issuer, current dates, place and contact. Use the notice builder or agreed submission route, then ask the reviewer how to track what was accepted.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the browser draft editor and a fictional arts-night notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Check corrections and take-downs","body":"When details change, contact the responsible reviewer with the original notice reference, confirmed new information, effective time and outlets. Ask what to do if an outdated version is still showing. Check the real display or ask the host before treating it as corrected.\n\nAfter review, check the actual outlet and tell the reviewer how to verify a correction or withdrawal. Keep the contact and expiry so the notice can be maintained.","captureNotes":"Walk through Publishing guide and public board with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-community-contributor' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Take a proposed local notice from receipt to a defensible publish, hold or correction decision.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Review against the original","body":"A Straddie Noticeboard Network reviewer works from the actual submitted notice, issuer and authority for each outlet. Open the review record and verify the source, permitted audience, timing and correction contact. A useful review gives a clear reason and one next action when more evidence is needed.\n\nMatch the draft with the named public source. Check the place, timing, publisher approval and permissions for people and images. Compare the content against the intended outlet and return unclear items to the issuer.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture a fictional draft and reviewed example from the public publishing guide. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The event flyer and draft disagree about the start time. How do you review it?","choices":[{"id":"a","text":"Ask the issuer to confirm its current source and resolve the mismatch first."},{"id":"b","text":"Use the draft''s time because it reached review later than the flyer."},{"id":"c","text":"Use the flyer time and leave the mismatch out of the decision record."}],"correct_choice_id":"a","explanation":"A reviewer should resolve the discrepancy with the responsible issuer.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A public photo is linked but its reuse permissions are unclear. Which action fits?","choices":[{"id":"a","text":"Approve the photo on a venue screen only because it will be seen briefly."},{"id":"b","text":"Ask for a cleared image or send the wording for review without the image."},{"id":"c","text":"Approve the image if the issuer can promise someone will check later."}],"correct_choice_id":"b","explanation":"The media permission must be clear for the planned use.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Record decisions, corrections and review continuity","body":"Keep the reviewer, scope, effective time, version, reason and expiry for clear, return or withdraw outcomes. Hand the cleared record to the authorised steward and arrange host verification for an affected notice. Log the next check for still-open outlets and privately route any complaint or permission change to the right owner.\n\nKeep the review decision, feed or display verification and unresolved handoff in the authorised record.\n\nHand the next reviewer the decision, currently authorised copy and any issuer check or urgent correction awaiting action.","captureNotes":"Walk through Pilot feed review and host check with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the review decision, feed or display verification and unresolved handoff using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A withdrawal has been cleared but a host is offline. How do you record this?","choices":[{"id":"a","text":"Close the check because the review withdraw action is complete."},{"id":"b","text":"Record the authorised withdrawal and keep display verification open with a named host and next check."}],"correct_choice_id":"b","explanation":"The operating record needs the review decision, feed or display verification and unresolved handoff. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the review decision, feed or display verification and unresolved handoff"},{"id":"b","text":"a review decision labelled displayed everywhere"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-editorial-review' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Keep the agreed notice record consistent across actual outlets and show how a correction, expiry or outage was handled.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Prepare the approved record","body":"The Straddie Noticeboard Network feed steward coordinates records across agreed outlets. Start with an approved notice, its source or record ID and the channel permissions. Identify which destinations are operating or rehearsed, who can promote a change and how to verify actual display. Set expiry and a fallback before release.\n\nFrom the reviewed copy, confirm the stable notice ID, source, responsible publisher, time checked, expiry and agreed outlets. Use the practice guide to rehearse a change under the same ID.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the public practice board with a staged feed example. Keep write access and credentials private. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved draft has an ID but no public source. What do you do?","choices":[{"id":"a","text":"Use the practice board URL as a substitute source."},{"id":"b","text":"Return it for a verifiable source before preparing the approved feed record."},{"id":"c","text":"Use a private review link as the public source so there is a link."}],"correct_choice_id":"b","explanation":"The public source should allow the responsible notice information to be checked.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A notice is withdrawn and one host is offline. What belongs in the handover?","choices":[{"id":"a","text":"A note that withdrawn means every screen is already clear."},{"id":"b","text":"A copy of the last approved notice so the venue can restore it."},{"id":"c","text":"The withdrawal, affected outlets, verification gap and who will check the offline display."}],"correct_choice_id":"c","explanation":"The feed decision and the visible screen state need separate verification.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Maintain fallbacks, recovery and the handover","body":"Record stale, disconnected and fallback outcomes, distinguishing the board’s service state from official emergency direction. Check backup and recovery with the authorised technical and venue owners. Give a successor release steps and safe rollback evidence, current issuers, contacts, open checks and upcoming expiries. Verify the authorised backup can restore a tested release without revealing private data.\n\nKeep current release and recovery status, outstanding removals and responsible owners in the authorised record.\n\nVerify the current copy at the receiving outlets. Leave the steward a release reference, unresolved receipt and explicit action to correct, expire or withdraw it.","captureNotes":"Walk through Screens and outages and emergency sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include current release and recovery status, outstanding removals and responsible owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A rollback restores an old notice that has since been withdrawn. What is the response?","choices":[{"id":"a","text":"Contain the affected display and restore or release the verified current record, then verify the affected outlets."},{"id":"b","text":"Keep the rolled-back version because the website is operational."}],"correct_choice_id":"a","explanation":"The operating record needs current release and recovery status, outstanding removals and responsible owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a backup version reference without rechecking withdrawal state"},{"id":"b","text":"current release and recovery status, outstanding removals and responsible owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-feed-steward' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check a venue display from source to screen and recover faults with an agreed fallback and handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Check display, connection and source","body":"A Noticeboard screen is maintained with the venue host and the network operator. Start with the display ID, site permission, correct source, normal hours and who can change the setup. Use a safe test notice to check what a visitor sees and how to mark a stale or unavailable service.\n\nUse the practice display to identify the device, outlet, last check and feed state. Compare it with a current source and report what appears on the actual screen.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Record the public practice screen and one fictional offline rehearsal. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A screen is powered but it shows an old notice. What do you investigate first?","choices":[{"id":"a","text":"The display, last successful check and whether the feed contains the current record."},{"id":"b","text":"Replace the screen immediately because old content always indicates a device fault."},{"id":"c","text":"Change the notice wording independently in the feed."}],"correct_choice_id":"a","explanation":"Checking the actual display and source helps locate the fault.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two screens report issues after a connection change. What does the log need?","choices":[{"id":"a","text":"One common fault name so both can be marked fixed together."},{"id":"b","text":"Distinct device and venue details, time, symptoms, checks and escalation owner."},{"id":"c","text":"Only the venue Wi-Fi name and a screenshot from the better screen."}],"correct_choice_id":"b","explanation":"Separate device records give owners something to verify.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Hand over maintenance, equipment and support","body":"Provide the asset or venue owner, setup records, fallback steps, condition, review date and outstanding faults. Include where approved instructions and backups live and who can act if replacement or specialist service is required. Arrange a test of the next operator’s access and contact route. Preserve event and incident records in the agreed place.\n\nKeep the equipment fault and maintenance history, authorised access and next check in the authorised record.\n\nAfter a repair, check current content on the actual screen. Give the host the fault history and someone to contact if verified information stops reaching the display.","captureNotes":"Walk through Venue log and setup checklist with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the equipment fault and maintenance history, authorised access and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A caretaker change leaves an intermittent fault with no owner. What belongs in the handover?","choices":[{"id":"a","text":"The device login and an informal note that the fault usually clears."},{"id":"b","text":"The device and fault, observed evidence, remaining operating condition and assigned owner and check date."}],"correct_choice_id":"b","explanation":"The operating record needs the equipment fault and maintenance history, authorised access and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the equipment fault and maintenance history, authorised access and next check"},{"id":"b","text":"device details with no owner or unresolved issues"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-screen-caretaker' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find a notice you can act on, verify a change and choose how to suggest or help maintain local information.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find a public notice","body":"The Straddie Noticeboard Network brings local event and service information together for phones, websites and screens. Open the public site and pick a notice that answers an actual question. Look for its issuer, location, current status, issue time and expiry. Use How it works to find the correction or publishing route. Check published information against the issuer if a decision depends on it.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture the public board and training page using a fictional notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    '$[1]', json('{"title":"Use the issuer’s current update","body":"A notice may tell you a ferry, hall or activity changed. Follow its issuer link or check with the responsible operator and compare the issue and expiry time. Pass on the confirmed current instruction, and tell a reviewer if an old copy is still showing."}'),
    '$[4]', json('{"title":"Choose a route to help","body":"Use the draft editor or training exercise to learn how to contribute, and the host or business route when you can provide a place or service. Confirm who can review and publish a real notice. Use the authorised contact for corrections and keep private information off public drafts.\n\nKeep the current issuer or venue link for changes. If the notice would leave someone stranded or confused, send a clear correction with source and timing.","captureNotes":"Walk through Submit, training and hosting pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-site-tour' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Decide whether hosting a noticeboard fits your venue, then agree the display, operating duties and correction route.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree what the screen is for","body":"A Straddie Noticeboard Network venue host can help people find useful local information. Start with a particular display or location, intended visitors and who can approve access, equipment and support. Agree what visitors should see, who maintains it and how to record a fault or stale notice.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture the public hosting or pilot page and a fictional venue setup. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Receive corrections and hand over hosting","body":"When a notice changes or is withdrawn, confirm what viewers see and report any remaining old copy. Record when checks occur, who receives faults and where the agreement and maintenance record are. At transition confirm custody, review dates and private support contacts.\n\nCheck that a visitor can read the display and find a current source. Agree who follows up on faults and how the venue can change or end the hosting arrangement.","captureNotes":"Walk through Venue log and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-venue-host' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Give visitors useful, current local information and hand over an uncertain or changed item to the right person.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Check in and find the current briefing","body":"A Straddie Noticeboard Network welcome shift needs a confirmed lead, site and current briefing. Ask which information you can explain, how to check changes and where to send a question you cannot resolve. A visitor may need a readable route or contact as much as a notice title.\n\nSee how the Straddie Noticeboard Network works | https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Use the public visitor and volunteer rehearsal. Leave real guest information off-screen. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Close the shift and transfer the next action","body":"Pass on the current location, source, when checked, unverified issues and who can decide them. Return any equipment and ask who can verify any agreed voluntary contribution record. Report concerns or personal matters privately to the responsible person.\n\nHand over any unresolved query with the source and timestamp. Tell the lead if people repeatedly struggle to find an answer, and suggest a clearer public route.","captureNotes":"Walk through Volunteer handover and venue contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='noticeboard-welcome-volunteer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check your Point Lookout Fishing Club membership, organise a first outing and find help when arrangements change.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Open your member area","body":"Start at the Point Lookout Fishing Club (PLFC) clubhouse. Check which activities are open, whether they need a booking and the contact for the day. For your member details, use your own sign-in. Ask the club to reconcile any missing access or renewal before relying on it.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Show the public clubhouse and an authorised adult demo account. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Prepare, check in and raise concerns","body":"Confirm the conditions, applicable fishing information, official notices and event briefing. Ask who can pause the activity and what gear and conduct are expected. Report a problem to the responsible lead, then follow any agreed handover or equipment return.\n\nAfter the outing, tell the outing lead what worked or needs adjustment. Ask before including another person''s image, catch location or private information in a shared record.","captureNotes":"Walk through Club event and fishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-adult-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Agree what the deputy can cover, keep meeting papers and minutes dependable and hand back any pending decision.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree shared responsibilities and covering limits","body":"At Point Lookout Fishing Club (PLFC), review the Secretary’s desk and the actual delegation with the Secretary before working. Confirm which duties you can carry out, when to ask the Secretary and where the reliable agenda and membership references live. Work from the current notice and agenda version.\n\nWalk the current workload with the Secretary on taking office. Identify who owns the meeting record, correspondence, newsletter assembly, member notices and records that need restricted access. Agree whether you are drafting, following up or providing formally authorised cover for a meeting or release. Use your own account and test the actual role access. Record when cover starts, ends and which decisions to escalate. Check the work list with the Secretary each week.\n\nKeep the shared workload, cover limits, approval owner and when the arrangement ends in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the shared workload, cover limits, approval owner and when the arrangement ends using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Secretary is away and you are asked to send an unapproved notice. What do you verify?","choices":[{"id":"a","text":"Send it because you are working from the same newsletter desk."},{"id":"b","text":"Check the agreed cover, the record of authority and whether the notice was cleared for that audience."}],"correct_choice_id":"b","explanation":"The operating record needs the shared workload, cover limits, approval owner and when the arrangement ends. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the shared workload, cover limits, approval owner and when the arrangement ends"},{"id":"b","text":"an informal note saying you are covering everything"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[7]', json('{"title":"Hand over correspondence, records and deadlines","body":"Bring the latest meeting and newsletter versions, notices, calendar, correspondence needing a reply, membership follow-ups and open AGM jobs to the handover. File references in the authorised location. Ask the Secretary to confirm restricted items and whether anything temporarily needs cover. Escalate a complaint or missing record through the agreed officer rather than sharing the content in a general list. Agree a check-in and have the incoming officer show they can find the work using their own authorised access.\n\nKeep an outstanding work list with current sources, private routes, cover and next review in the authorised record.\n\nReturn a concise handover with the reviewed version, outstanding item and named owner. Escalate a missing permission or unresolved discrepancy through the Secretary.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include an outstanding work list with current sources, private routes, cover and next review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An unresolved complaint is linked to a task due after the transition. What do you hand over?","choices":[{"id":"a","text":"The restricted reference, authorised contact, next action and deadline, with access verified."},{"id":"b","text":"A copy in the shared newsletter folder so the next officer can find it easily."}],"correct_choice_id":"a","explanation":"The operating record needs an outstanding work list with current sources, private routes, cover and next review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a single public copy of the inbox and task list"},{"id":"b","text":"an outstanding work list with current sources, private routes, cover and next review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Use the club’s cadet route to agree a first activity, supervision, pickup and sharing choices with a guardian.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Plan the first visit together","body":"At Point Lookout Fishing Club (PLFC), start with the activity lead and the guardian. Confirm which cadet activities are open, their conditions and who supervises. Agree arrival, pickup and what gear or help is needed. Use the club’s approved guardian route for permissions.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Use a fictional family and the public membership information. Keep details of real young people private. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Photo choices and speaking up","body":"Ask how attendance, photography and online access are handled separately. The guardian and cadet can ask about where a record is shared and use the agreed private contact for a concern. Follow up after the session if access, pickup or a safety arrangement was unclear.\n\nBefore leaving, confirm the guardian knows who to contact and how to raise a concern or change a sharing choice.","captureNotes":"Walk through Clubhouse terms and designated safeguarding contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-cadet-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check which club activity is available to a casual participant, what the session requires and how to get a confirmed place.',
