UPDATE learning_course_versions SET
  description='Choose a suitable junior activity and confirm access, supervision and follow-up with the club and a guardian.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose an activity with your guardian","body":"At Point Lookout Fishing Club (PLFC), have the young person, guardian and activity lead agree on the activity level and participation details. Use the public clubhouse to find the programme, then the approved club route for bookings and any private information. Confirm the contact and pickup arrangement.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Show the public youth application choice and fictional event details. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Activity rules and follow-up","body":"Ask who explains the session or competition rules, demonstrates equipment and confirms how any result can be shared. Let the lead know when you need help or want to stop. At the end return equipment and discuss feedback and future participation with your guardian.\n\nAgree an approachable way for the junior participant to ask for help or step back. Take one piece of feedback to the activity lead if it could make the next activity easier.","captureNotes":"Walk through Club event and results information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/ Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance."}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-junior-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Confirm a lifetime membership record and agree any later contribution, mentoring or archive sharing separately.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Update your connection with the club","body":"Point Lookout Fishing Club (PLFC) manages lifetime membership through its club records. If access or a historic entry needs checking, ask the Secretary to verify it alongside the source record. Discuss any offer to mentor, share photographs or help at an event directly with the relevant lead.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Show the demo sign-in and a fictional member contact update. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Agree mentoring or support","body":"Discuss what you can comfortably offer, what the event lead needs and who supervises. Confirm equipment custody, timing and how to share feedback. Hand over unfinished work or historical context to the appropriate officer using the club’s preferred record.\n\nMake any archive contribution usable with credit, date, permission and a contact for corrections. Agree a supervised mentoring role if the activity lead needs one.","captureNotes":"Walk through Club events and officer contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-lifetime-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Take over a Point Lookout Fishing Club office with a clear appointment, access, record trail and first-week priorities.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Confirm appointments, rules and who owns the work","body":"Start with the incoming and outgoing Point Lookout Fishing Club (PLFC) officers and the Secretary. Confirm the appointment record, current adopted rules and effective date. Locate the relevant committee desk using your own authorised account. List the records, upcoming decisions and incomplete jobs that need a named owner.\n\nCheck the appointment record, actual current rules and decisions affecting each office. Find the five named officer guides. Use the shared handover to identify backup cover, who may approve or publish and which items come back to the committee or members. The V1.2 clubhouse archive should be checked against the club’s adopted records before using notice, quorum or election procedures. List unresolved appointments, approvals and deadlines early.\n\nKeep the verified appointment and rules references, handover scope and owners in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the verified appointment and rules references, handover scope and owners using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The website displays an office but there is no signed appointment record. What do you do?","choices":[{"id":"a","text":"Check the actual decision and approved rules with the Secretary before recording authority."},{"id":"b","text":"Assign duties based on what appears in the navigation."}],"correct_choice_id":"a","explanation":"The operating record needs the verified appointment and rules references, handover scope and owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an officer list copied from the site"},{"id":"b","text":"the verified appointment and rules references, handover scope and owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[7]', json('{"title":"Confirm first-week priorities and close the handover","body":"Schedule a first-week review of the most time-sensitive governance, membership, finance and event tasks. Confirm every gap has an owner, evidence to obtain and a deadline. Walk the incoming team through one decision, a follow-up and a restricted case handoff. Revisit outstanding dates and ask the responsible officers to confirm what was resolved. File the agreed handover and date for checking remaining matters.\n\nKeep a dated completion and exceptions record with evidence and follow-up owners in the authorised record.\n\nRecord the record owner, access needed, earliest deadline and who will cover while a gap is resolved. Arrange a first-week check with the outgoing officer or chair to confirm the handover works.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a dated completion and exceptions record with evidence and follow-up owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The successor can sign in but has not found the approved event decision. Can the transfer be closed?","choices":[{"id":"a","text":"Close the transfer and ask them to reconstruct it later from public updates."},{"id":"b","text":"Keep that check open with a named person, source to find and review date."}],"correct_choice_id":"b","explanation":"The operating record needs a dated completion and exceptions record with evidence and follow-up owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a dated completion and exceptions record with evidence and follow-up owners"},{"id":"b","text":"a signed attendance sheet with no review of open work"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-officer-handover' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Chair decisions, oversee officers and take ownership of the open commitments that need the President’s attention.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Take up the chair and agree delegations","body":"Point Lookout Fishing Club (PLFC) is a local club with its own rules. Start the President''s handover by checking the appointment and current rules with the Secretary. Review the signed-in committee agenda, officer delegations and open decisions. Ask each responsible officer what is ready for a decision and what needs support or more evidence.\n\nStart with the club’s confirmed appointment record and current adopted rules. The clubhouse V1.2 archive has an unverified adoption date. Ask the Secretary which rules are in force and where the evidence is kept. Agree which decisions sit with members, the committee or a delegated officer, and what the Vice President can cover. Check any pending grant, venue or supplier promise against its authority before representing it as agreed. Record the limits and review date with the handover.\n\nKeep the appointment reference, adopted-rules reference and current authority limits in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the appointment reference, adopted-rules reference and current authority limits using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A sponsor asks you to confirm an offer that appears in a draft budget. What do you check first?","choices":[{"id":"a","text":"Sign within the estimate because the President represents the club."},{"id":"b","text":"Check the current rules, recorded decision, limits and who can accept the offer."}],"correct_choice_id":"b","explanation":"The operating record needs the appointment reference, adopted-rules reference and current authority limits. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the appointment reference, adopted-rules reference and current authority limits"},{"id":"b","text":"the website role badge and the latest budget"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[7]', json('{"title":"Hand over the whole office","body":"Do a dated walkthrough with the incoming President. Open the next agenda, last decisions, outstanding concerns, finance overview, calendar, public statements and agreement review dates. Name an owner for each open obligation and show which records are private. Have the Webmaster verify their individual access and review the outgoing access. Set a first-week meeting to check missed decisions, role coverage and unresolved issues. File the handover reference in the club’s authorised records.\n\nKeep a dated handover with records, authority gaps, actions, access checks and the first-week review in the authorised record.\n\nAgree which decision can advance next, who is responsible for each action and when its progress will come back to the committee.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a dated handover with records, authority gaps, actions, access checks and the first-week review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming President has access but cannot find the authority for an upcoming event. What closes the handover gap?","choices":[{"id":"a","text":"Find or escalate the missing decision, agree who verifies it and record the date for checking again."},{"id":"b","text":"Treat successful sign-in as verification that all handover work is complete."}],"correct_choice_id":"a","explanation":"The operating record needs a dated handover with records, authority gaps, actions, access checks and the first-week review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a sign-in confirmation and a general list of committee contacts"},{"id":"b","text":"a dated handover with records, authority gaps, actions, access checks and the first-week review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-president' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run the club’s meeting, correspondence and membership records from current authority through to a dependable handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Verify authority, rules and the club’s record calendar","body":"Point Lookout Fishing Club (PLFC) has its own adopted rules. Start with the appointment, actual rules and records calendar, then open the secretarial committee work areas under your own access. Check the last approved minutes, outstanding agenda items, correspondence and renewal activity with the outgoing officer.\n\nOn taking office, confirm the appointment, current adopted rules and the authorised home for correspondence, registers, minutes and company or club records. The online V1.2 archive is a reference until you confirm registration and adoption evidence. Build a calendar for meetings, member reminders, AGM reports, required notifications and renewals. Use current Queensland Fair Trading guidance to confirm which filings and deadlines apply. Agree deputy coverage and what needs the Treasurer, Chair or Webmaster.\n\nKeep the filing calendar, adopted-rules reference, responsible officer and authorised records folder in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the filing calendar, adopted-rules reference, responsible officer and authorised records folder using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Your shared calendar lists a filing date copied from an old term. What should you do?","choices":[{"id":"a","text":"Check current official requirements and the record that sets the date, then assign a filing owner."},{"id":"b","text":"Keep the old date unless a reminder from the regulator arrives."}],"correct_choice_id":"a","explanation":"The operating record needs the filing calendar, adopted-rules reference, responsible officer and authorised records folder. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an old officer diary with reminders but no source"},{"id":"b","text":"the filing calendar, adopted-rules reference, responsible officer and authorised records folder"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[7]', json('{"title":"Hand over retained records and pending business","body":"Prepare a dated transfer with the current rules, latest signed records, next notices, nominations or filings, private correspondence and register controls. Identify owners of outstanding actions, access, member issues and public replies. Hand over a reference to archived records and club property rather than copying private content into training. Agree who can complete the filings, confirm individual access with the Webmaster and review outstanding matters within the first week.\n\nKeep a handover register with document references, filing evidence or gaps, access and a review date in the authorised record.\n\nHand over a calendar of actual deadlines, authoritative versions and the person who owns each open decision. Explain how to find restricted records without copying their contents.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a handover register with document references, filing evidence or gaps, access and a review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Secretary finds a missing filing receipt. How should you close the transfer?","choices":[{"id":"a","text":"Mark it filed because the paperwork is signed and stored in the right folder."},{"id":"b","text":"Flag it as an open verification, find the responsible person and confirm the source or next contact."}],"correct_choice_id":"b","explanation":"The operating record needs a handover register with document references, filing evidence or gaps, access and a review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a handover register with document references, filing evidence or gaps, access and a review date"},{"id":"b","text":"a shared login and a checklist full of assumed completions"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-secretary' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the public club pages, member sign-in and the right person to ask before a first visit or booking.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Start with the public clubhouse","body":"Start with the public clubhouse for Point Lookout Fishing Club (PLFC). Use the public programme and contact information to find a confirmed outing or ask about a visit. The club’s signed-in member and committee areas serve different roles. If a page is a preview, check the actual event or access with the club.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Record the demo homepage, calendar and fishing guide using public or fictional examples. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Find the right help for an issue","body":"Use the organiser for event details, the club contact for membership and Webmaster help for access. Use official authorities for current fishing or emergency advice. Keep account details and private records out of a public enquiry and report site errors with the page and issue.\n\nChoose a confirmed activity or send one concrete question to the club. Keep its response with the date, meeting point and contact before making plans.","captureNotes":"Walk through Club contact, Webmaster help and public sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-site-tour' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find a gathering you can attend and agree any offer to help with the people running it.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find a gathering","body":"At Point Lookout Fishing Club (PLFC), open the public clubhouse and look for a confirmed gathering. Ask the organiser who can attend, whether an RSVP is needed and what support would make participation easier. If you want to help, name the task and check that the organiser can brief you.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Show a fictional social meet in the public demo calendar. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Close the loop after a gathering","body":"Check the current announcement before travelling. If a plan changes, use the organiser’s update rather than spreading unverified details. Return borrowed items and report any issue privately to the lead. Choose which photos or names are cleared before posting.\n\nAsk the organiser whether there is another suitable activity or a particular task they need help with. Pass on changes with a person and date so the next attendee has current information.","captureNotes":"Walk through Club event information and member updates with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-social-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Take over the club’s financial controls, maintain clear evidence and prepare a usable financial report and handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Take over the accounts and payment authority","body":"At Point Lookout Fishing Club (PLFC), check the appointment, actual payment authority and the last reconciliation with the outgoing Treasurer. Locate the finance and club shop workspaces under your own permissions. Agree who can authorise, pay and review each kind of commitment.\n\nConfirm the Treasurer appointment, current rules, committee financial decisions and authorised finance systems. Check bank and payment provider account holders, monetary limits, approving officers, recurring bills, insurance or other commitments and private ledger access. Save an opening balance and outstanding item list from the prior authorised record. Have changes to bank or system access processed by the provider and authorised administrator, with an independent check and no shared sign-ins.\n\nKeep the opening balances, payment authority, current commitments and role access status in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the opening balances, payment authority, current commitments and role access status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supplier asks you to use the former Treasurer’s login for a transfer. What is the proper next step?","choices":[{"id":"a","text":"Use the previous login while the bank updates the role."},{"id":"b","text":"Confirm your own authorised access and check the payment approval before acting."}],"correct_choice_id":"b","explanation":"The operating record needs the opening balances, payment authority, current commitments and role access status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the opening balances, payment authority, current commitments and role access status"},{"id":"b","text":"a bank link and the outgoing officer’s password"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[7]', json('{"title":"Hand over private finance work","body":"Walk the successor through reports, bank and ledger reconciliation, grants and asset register. List upcoming payments, unresolved refunds, waiver or invoice checks, report and tax or filing dates where applicable and authorised contacts. Hand over devices, physical records and cash using a custody record and verified count. Check independently that incoming access works and outgoing access has been reviewed. Give the newsletter only the approved summary for its audience. Schedule the first reconciliation review.\n\nKeep opening balances and access checks, liabilities, private source records and named follow-up in the authorised record.\n\nShow receipts, reconciled balances, unresolved variances and the next approval dates. Give the next officer the safe access and record route separately.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include opening balances and access checks, liabilities, private source records and named follow-up using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Treasurer can see the ledger but cannot verify last month’s bank reconciliation. What should stay open?","choices":[{"id":"a","text":"The source and approver needed, a named person to resolve the gap and a check-in date."},{"id":"b","text":"The handover can be closed because the balance is on the dashboard."}],"correct_choice_id":"a","explanation":"The operating record needs opening balances and access checks, liabilities, private source records and named follow-up. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an exported report sent to a general committee list"},{"id":"b","text":"opening balances and access checks, liabilities, private source records and named follow-up"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-treasurer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Take clear chair cover, keep club work moving and resolve dependencies with the people who own them.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree delegation and chair cover","body":"At Point Lookout Fishing Club (PLFC), use the actual appointment and delegation record to check what the Vice President may cover. Meet the President and Secretary and locate the agenda, open actions, activity leads and upcoming decisions. Confirm who decides if cover or authority is unclear.\n\nRead the confirmed appointment and current rules with the President and Secretary. Agree what you will lead or follow up, what is reserved for the President or committee and how somebody records cover if circumstances change. Before leading a meeting check its type, notice, quorum, conflicts and chairing procedure. If you cannot verify your authority, ask the Secretary to record the issue and arrange the next step.\n\nKeep the cover, limits, meeting basis and decisions still needing referral in the authorised record.\n\nIf deputising as Chair, check the recording plan with the Secretary. Know who runs the recording, who checks the outside feed and who can stop it before closed business. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the cover, limits, meeting basis and decisions still needing referral using invented details. Show the PLFC meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The President is absent and an extra motion requires authority outside the cover agreement. How do you proceed?","choices":[{"id":"a","text":"Use the verified rules and seek the appropriate decision route before acting on the extra motion."},{"id":"b","text":"Treat taking the chair as full authority to decide on the extra business."}],"correct_choice_id":"a","explanation":"The operating record needs the cover, limits, meeting basis and decisions still needing referral. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the calendar invitation and the absent officer’s title"},{"id":"b","text":"the cover, limits, meeting basis and decisions still needing referral"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[6]', json('{"title":"Hand over deputy and event responsibilities","body":"Walk the next Vice President through coverage limits, agenda and decisions, active calendar, approaching events, outstanding gear or supplier issues and people the club is in discussion with. Show the duty roster and unresolved permissions or risks. Hand back any property and have access checked by the Webmaster. Confirm the shortlist of open decisions with the President and set the first-week check.\n\nKeep the event and authority register, gear and commitments, named owner and dated next review in the authorised record.\n\nReturn chair cover with the decision reference, owner and due date, and name the next person for any unresolved event or partner question.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the event and authority register, gear and commitments, named owner and dated next review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft agreement expires between officers. What do you pass on?","choices":[{"id":"a","text":"The exact status, responsible officer, decision needed and last date for review."},{"id":"b","text":"The partner’s details with a suggestion to contact them sometime."}],"correct_choice_id":"a","explanation":"The operating record needs the event and authority register, gear and commitments, named owner and dated next review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the next meet title and a list of interested people"},{"id":"b","text":"the event and authority register, gear and commitments, named owner and dated next review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-vice-president' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Agree a suitable club shift, get briefed and hand back equipment and any outstanding concern.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree on the shift","body":"Point Lookout Fishing Club (PLFC) offers ways to help through its activity leads. Start with a confirmed event or job and ask who is running that shift. Agree the task, limits, supervision and check-in. A suitable role fits the club’s needs and the time, access and support agreed with the volunteer.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    '$[5]', json('{"title":"Return custody and review what happened","body":"Count and hand back borrowed items with the lead. With any cash or collections, follow the authorised handover and count already agreed. Pass the next person the task status, what remains and who owns it. Check who can confirm any voluntary contribution record and keep feedback or sensitive matters within the right audience.\n\nFinish with the agreed equipment returned and a useful update to the lead. If the task and support are a poor fit, ask about a different shift or practice route.","captureNotes":"Walk through Event close-out and equipment handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-volunteer-onboarding' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Maintain the club’s site and individual access, verify the real permission boundary and leave a recoverable handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Establish authority and service ownership","body":"Start with the Point Lookout Fishing Club (PLFC) owner or authorised officer. Confirm service ownership, the Webmaster appointment and the systems you may access. Identify who can approve publishing and membership changes, then use the Webmaster area and a controlled role test before issuing new access.\n\nConfirm the Webmaster’s appointed scope and responsible club contacts. Make an inventory of the clubhouse, existing domain or publishing services, repository, database, payment links, provider accounts and backups with their owners. Distinguish the club’s existing public website from the separate clubhouse deployment and record any approved connection work. Document what the lower-risk test environment can show and who may make changes.\n\nKeep the service and asset inventory, exact scope, authority and approved contacts in the authorised record.\n\nOpen the Point Lookout Fishing Club clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the service and asset inventory, exact scope, authority and approved contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A club officer asks to point the legacy public domain at the clubhouse. What do you check?","choices":[{"id":"a","text":"The approved decision, domain owner, scope and rollback before scheduling any change."},{"id":"b","text":"Change it as soon as the clubhouse is reachable because it serves the same club."}],"correct_choice_id":"a","explanation":"The operating record needs the service and asset inventory, exact scope, authority and approved contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a list of login addresses with no owner or decision"},{"id":"b","text":"the service and asset inventory, exact scope, authority and approved contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    '$[6]', json('{"title":"Hand over accounts and unfinished work securely","body":"Transfer the service map, recent deploy references, backup and restore evidence, open support issues, renewals, availability and authorised administrators. Arrange provider role changes through individual accounts. Hand over equipment and recovery custody using the approved process and confirm the next contact for urgent issues. Check outgoing access, confirm the incoming officer can run an authorised release and set a review date.\n\nKeep dated transfer references, recovery locations, role checks, unfinished work and successor review in the authorised record.\n\nGive the responsible officer the live status, recovery owner and any follow-up, including how to withdraw access when an office changes.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include dated transfer references, recovery locations, role checks, unfinished work and successor review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Webmaster has repo access but cannot reach the cloud deployment or recovery settings. What should you do?","choices":[{"id":"a","text":"Record the scope gap, get the approved access decision and test both responsibilities after changes."},{"id":"b","text":"Use a personal administrator''s account for provider updates until the next term."}],"correct_choice_id":"a","explanation":"The operating record needs dated transfer references, recovery locations, role checks, unfinished work and successor review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a code repository link and a private password copied into the pack"},{"id":"b","text":"dated transfer references, recovery locations, role checks, unfinished work and successor review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='plfc-webmaster' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Choose the correct club recording protocol, give people fair notice and deliver checked minutes, transcripts and recordings to the right audience.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Use the club’s rule and assign the jobs","body":"Identify the club, meeting type and governing authority before preparing the capture. PLFC uses its own meeting decision and participant consent. Sandy is in formation. Its draft constitution Rule 4B calls for full video and audio for committee and general meetings, including the AGM, from opening to close without pausing. The Secretary is responsible for recording and archiving. The Secretary or Assistant Secretary makes the recording, and Film Club crew may operate the equipment. Officers with Members and publishing access under Schedule 1 approve public streams. Check who will minute, record, operate, approve and verify the feed before the meeting.\n\nPLFC clubhouse | https://plfc-clubhouse.auraofintelligence.workers.dev/\nSandy Rule 4B meeting workflow | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","captureNotes":"Compare the PLFC recording panel and Sandy’s Rule 4B flow. Show a fictional roster with the Secretary, deputy, crew operator and public publishing officer. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Film Club producer has an encoder and a draft public listing. Who approves a Sandy public meeting stream?","choices":[{"id":"a","text":"Anyone rostered on the Film Club crew."},{"id":"b","text":"An officer with Members and publishing access under Schedule 1."},{"id":"c","text":"The person with the fastest uplink."}],"correct_choice_id":"b","explanation":"The Secretary coordinates recording and archiving, and the designated Schedule 1 group approves the public stream.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Which Sandy meetings does Rule 4B(a) explicitly include?","choices":[{"id":"a","text":"Only AGMs and meetings that pass a separate recording motion."},{"id":"b","text":"Every informal working-group chat."},{"id":"c","text":"Every committee and general meeting, including the AGM."}],"correct_choice_id":"c","explanation":"Rule 4B(a) covers formal committee and general meetings. A public forum also has the public stream rule in Rule 4B(d).","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[5]', json('{"title":"File Sandy’s permanent archive and verify access","body":"For Sandy, preserve the original video, audio and transcript on club-controlled hosting with the correct audience. Open the meeting’s minutes step and save stable HTTPS links in Meeting archive (rule 4B). Keep the minutes in the corresponding official meeting record. Check Watch, Listen and Transcript under My Membership, Notices & newsletters, Meeting archive. Test the actual media links with a member and a signed-out view. The site controls who sees its index. The hosting service must enforce the same audience for member-only files. Rule 4B keeps the recordings and transcripts permanently without edits. If a link moves, replace it through the archive so history records the old link, and check a restored backup. For PLFC, follow its own approved records schedule and access arrangements.\n\nGive the organiser a brief whose links, audience, retention and minutes status can be verified. Provide an accessible transcript or replay route in line with the club’s rules and record who handles corrections.","captureNotes":"Use a fictional meeting’s step 3 archive form and the member Notices tab. Test both hosting audiences and show how replacing a broken URL retains link history. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A Sandy member archive video is indexed behind sign-in, but the video URL plays for anyone. What is the next action?","choices":[{"id":"a","text":"Assume the Sandy sign-in protects the video once someone copies its URL."},{"id":"b","text":"Move the same link into the public Island News listing."},{"id":"c","text":"Set appropriate access at the host and repeat member and signed-out checks."}],"correct_choice_id":"c","explanation":"Portal visibility and the media host’s own link permissions are separate controls.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The server migration changes the archived recording''s URL. What is the correct handoff?","choices":[{"id":"a","text":"Preserve the original recording and replace its link through the archive, retaining the link history."},{"id":"b","text":"Clear the archive field and delete the old master."},{"id":"c","text":"Trim the recording before moving it to the new store to save space."}],"correct_choice_id":"a","explanation":"The archive permits a replacement link and keeps the old reference. The record itself is permanent.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='meeting-media-operator' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Use an AI tool for a defined local work task, check the result and give the next person something they can trust.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Pick a real task and agree what can be shared","body":"Ready SETCO supports practical skills for local work and community projects. Choose a task with a named owner and a clear result, such as turning an approved public event plan into a checklist. Ask what information may be shared with the chosen tool, use fictional or cleared inputs and name a source to check answers against. Save the parts a colleague can reuse, with the decisions and corrections that need human review. The person responsible for the real work signs off before the output is used.\n\nSee practical learning and training | https://ready-setco.auraofintelligence.workers.dev/jobs.html","captureNotes":"Record an example in a chosen tool using made-up inputs. Show the prompt and draft as separate items. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"An organiser asks for a crew checklist and shares private participant details. What should happen first?","choices":[{"id":"a","text":"Paste the full list so the tool understands the event."},{"id":"b","text":"Agree which inputs the tool may receive and use a cleared or fictional brief for the checklist."},{"id":"c","text":"Send the file anonymously and assume that makes it public."}],"correct_choice_id":"b","explanation":"A defined task can usually be tested without giving a tool unrelated private information.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The tool suggests an access route the venue has not confirmed. What goes in the handover?","choices":[{"id":"a","text":"Give it to visitors as an approved route."},{"id":"b","text":"Remove the caveat because the instructions are easy to read."},{"id":"c","text":"Flag it for the venue lead to verify and show the source that was checked."}],"correct_choice_id":"c","explanation":"A useful handover distinguishes checked facts from questions still waiting on the responsible person.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html"]}]}'),
    '$[5]', json('{"title":"Hand over the result and recognise when to stop","body":"Record the verified final version, responsible person, source date and what you corrected. Keep private or unsafe information out of the shared prompt. Identify an escalation for disputed content, a wrong release or a provider change and ask the team to confirm any later revision. Keep it possible for someone else to repeat the checks.\n\nKeep the corrected output, release destinations, responsible review and next check in the authorised record.\n\nGive the next person the checked output, source, unresolved concern and human owner. Include enough context to repeat the task or review a correction later.","captureNotes":"Walk through Checked version and feedback log with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the corrected output, release destinations, responsible review and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supervisor spots an error after the checklist was shared. What should happen?","choices":[{"id":"a","text":"Verify impact, correct or remove the affected version through the owner and tell the people who rely on it."},{"id":"b","text":"Quietly edit the copy and leave previously distributed versions alone."}],"correct_choice_id":"a","explanation":"The operating record needs the corrected output, release destinations, responsible review and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a revised prompt with no account of the released version"},{"id":"b","text":"the corrected output, release destinations, responsible review and next check"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-ai-work-skills' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Follow an idea from meeting preparation to an authorised decision, assigned work and a dependable handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find the authority before setting the agenda","body":"Ready SETCO is forming as a cooperative, and clubs and community organisations have their own rules. Start with the actual organisation, meeting type and version of the rules it uses. Ask the convenor or Secretary who can call the meeting, decide the item and record the result. Give people an accessible agenda with the decision sought, source papers and time to consider them. A proposal can stay open for consultation while authority or evidence is being confirmed.\n\nExplore formation and governance | https://ready-setco.auraofintelligence.workers.dev/formation.html","captureNotes":"Walk through Formation and governance with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the organisation status, current rules, authority and decision responsibilities using invented details.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A project is under discussion and someone circulates a message saying the co-op approved it. What is the next step?","choices":[{"id":"a","text":"Treat the message as an approval."},{"id":"b","text":"Check the actual authority and decision record, correct the message and show what remains open."},{"id":"c","text":"Make the same assumption for every connected club."}],"correct_choice_id":"b","explanation":"The organisation and meeting authority determine what can be decided and recorded.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/formation.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"An agenda item would affect people who have not seen the source papers. What can the convenor do?","choices":[{"id":"a","text":"Ask everyone to agree before receiving the papers."},{"id":"b","text":"Publish private attachments and invite public comments."},{"id":"c","text":"Share the appropriate material in a usable form and give reasonable time for input."}],"correct_choice_id":"c","explanation":"People can contribute to a sound decision when they can understand the evidence and scope.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/formation.html"]}]}'),
    '$[5]', json('{"title":"Operate the cycle and hand over","body":"Keep a current list of meetings, formal returns where relevant, reports, event changes, renewals, supporting records and obligations. At transition, verify access for incoming and outgoing colleagues, custody of property, revised authority and actual acceptance by others. Walk the successor through live tasks, disagreements and privacy limits and agree a first-week review and open deadlines. Use a dated source for each task.\n\nKeep the dated roles, records, access checks and concrete open tasks in the authorised record.\n\nBefore closing the record, check that affected people know the decision, how to seek a correction and when the action comes back for review. Offer a clear explanation or an accessible copy where needed.","captureNotes":"Walk through Formation planner and Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the dated roles, records, access checks and concrete open tasks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"All accounts work but a pending filing and decision cannot be found. Does handover close?","choices":[{"id":"a","text":"Close since access works and the successor can start a new record."},{"id":"b","text":"Keep the source and filing checks open with owners and dates, and verify them at the next check-in."}],"correct_choice_id":"b","explanation":"The operating record needs the dated roles, records, access checks and concrete open tasks. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the dated roles, records, access checks and concrete open tasks"},{"id":"b","text":"an access checklist with no obligations or outstanding decisions"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-committee-basics' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Plan a real community event or a rehearsal, give crew a clear brief and keep attendees informed when arrangements change.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Turn a proposed event into a workable brief","body":"Ready SETCO helps organisers, crews and people learning a role work from the same plan. Start with the event lead and check which date, site, activity and resources are confirmed. The run sheet needs a named owner for each task, accessible arrival information, the paid or voluntary arrangement, and a fallback. Ask the event lead to address missing permissions or safety before people are rostered. Give helpers one clear briefing with a way to raise a concern, including if their shift or travel changes.\n\nSee the community events route | https://ready-setco.auraofintelligence.workers.dev/events.html","captureNotes":"Record a fictional event run sheet and point out the owner, due time and backup in each row. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A session has a date but no confirmed site or access contact. What goes on the crew brief?","choices":[{"id":"a","text":"Send the address as final so the crew can plan."},{"id":"b","text":"Mark the site pending, name who checks permission and agree when to confirm before rostering."},{"id":"c","text":"Make each volunteer find another location independently."}],"correct_choice_id":"b","explanation":"A useful brief shows which decisions are still open and who makes them.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/events.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A new helper asks for a role they can do seated. What is the next step?","choices":[{"id":"a","text":"Tell them to show up and choose a job on the spot."},{"id":"b","text":"Move them to a paid duty without discussing its terms."},{"id":"c","text":"Ask the lead to agree a suitable task, equipment and a check-in within the actual crew plan."}],"correct_choice_id":"c","explanation":"A brief that fits real needs lets people contribute reliably.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/events.html"]}]}'),
    '$[5]', json('{"title":"Close out, debrief and hand over","body":"Check attendance or results appropriate to the event, asset return, incidents, unresolved costs and actual messages. Keep agreed records and approve which feedback or photos may be shared. Assign every open action and hand the next team the current run sheet, unresolved issues and where to verify the source.\n\nKeep a verified close-out with open costs or faults, permissions and next owners in the authorised record.\n\nAsk an attendee and someone new to the crew what made the event easier or harder to use. Agree one improvement, who can implement it and before which next session.","captureNotes":"Walk through Event debrief and asset record with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include a verified close-out with open costs or faults, permissions and next owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The event finished but several loaned items have not been checked back in. What should the lead do?","choices":[{"id":"a","text":"Record custody and open follow-up per item, with responsible people and review time."},{"id":"b","text":"Close the event and let the equipment owner send a list later."}],"correct_choice_id":"a","explanation":"The operating record needs a verified close-out with open costs or faults, permissions and next owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a finished date and generic comments about what went well"},{"id":"b","text":"a verified close-out with open costs or faults, permissions and next owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-crew' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Make a place record someone can understand, verify and correct, with the appropriate permissions and custody attached.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree the purpose and the place record","body":"Ready SETCO''s public map accepts place suggestions for review. Start with a useful observation, such as a missing public facility pin or a changed access detail. Open Map and use the place suggestion route. Record location, date, source and what can be shared. If the information is restricted, sensitive or culturally governed, ask the appropriate custodian about the scope before collecting or proposing publication. The public reviewer checks a suggestion before it is displayed.\n\nOpen the public map | https://ready-setco.auraofintelligence.workers.dev/map.html\nRead about permissions and support | https://ready-setco.auraofintelligence.workers.dev/boundaries.html","captureNotes":"Use a fictional map entry and the Ready SETCO public map or Cultural Intelligence Node reference material. Do not submit a live example. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Someone suggests adding a significant place to the public map and its location may be restricted. What should happen first?","choices":[{"id":"a","text":"Publish the exact coordinates and invite corrections."},{"id":"b","text":"Clarify the intended use and ask the appropriate custodian before collecting or publishing the location."},{"id":"c","text":"Copy coordinates from another person''s notes and assume consent."}],"correct_choice_id":"b","explanation":"The person who holds a record and the person authorised to approve sharing may be different.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/map.html","https://ready-setco.auraofintelligence.workers.dev/boundaries.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What helps a map reviewer verify an ordinary public facility correction?","choices":[{"id":"a","text":"An unlabelled screenshot from an old map."},{"id":"b","text":"A request to replace every nearby place record."},{"id":"c","text":"The observed change, location, date and a source or named contact they can check."}],"correct_choice_id":"c","explanation":"Useful provenance lets a reviewer check what changed and when.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/map.html","https://ready-setco.auraofintelligence.workers.dev/boundaries.html"]}]}'),
    '$[5]', json('{"title":"Transfer custody and future decisions","body":"Prepare an index of source records, approved copies, date reviewed, access limits, responsible custodians and open questions. Acknowledge any restrictions on copying, publication or use by a new audience. Ask the incoming person to verify access and show how they would handle a correction, expiry or withdrawal with the appropriate authority.\n\nKeep the approved transfer, source, restrictions, current public version and named review in the authorised record.\n\nLeave the authorised person the record reference, source, intended use and correction contact. If use needs separate permission, record who can consider it before the work is shared.","captureNotes":"Walk through Place records handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the approved transfer, source, restrictions, current public version and named review using invented details. Confirm the relevant custodian’s directions and privacy obligations for the actual organisation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new team wants to reuse the record for a wider audience. What should be checked before transfer or release?","choices":[{"id":"a","text":"Treat permission to store the record as permission to publish it more widely."},{"id":"b","text":"The original scope and custodian’s decision on wider use, with the current approved version and restrictions."}],"correct_choice_id":"b","explanation":"The operating record needs the approved transfer, source, restrictions, current public version and named review. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the approved transfer, source, restrictions, current public version and named review"},{"id":"b","text":"an export of source and public content without any use limits"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-digital-stewardship' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Bring a real local staffing, training or service need into the formation conversation, and see how a contribution becomes an agreed responsibility.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Put one local need on the table","body":"Ready SETCO is the proposed Ready Sustainable Employment and Training Cooperative on Minjerribah / North Stradbroke Island. Businesses, clubs and community leaders can help decide how it will operate. Start at Take part and choose the employer or community route. Name one real need the co-op could help with, one contribution the organisation could explore, and a person who can discuss it. For example, a venue might need dependable host shifts and be able to offer supervised practice. The formation discussion can then compare employers, training leads and shared resources. Any offer needing money, staff time, access or a contract moves to the relevant decision-maker for written agreement.\n\nSee how formation decisions work | https://ready-setco.auraofintelligence.workers.dev/formation.html\nSend a formation enquiry | https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title","captureNotes":"Capture the public participation and formation pages with a fictional local employer. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[1]', json('{"title":"Take the offer to the right decision-maker","body":"Put the need and proposed contribution in writing with the next decision and deadline. The business confirms its authority, costs and staffing. The formation group confirms whether the proposal fits the community’s priorities and who can take it forward. Invite information from staff, trainees and local users who will be affected. Agree how to record a small rehearsal, another discussion or a formal approval, and who will tell each person involved."}'),
    '$[2]', json('{"title":"Compare ways to meet the need","body":"Take a practical case. A local venue has irregular event work and needs enough trained crew without overcommitting staff. Compare a paid recruitment enquiry, shared crew training and a genuinely separate volunteer role with its own purpose and lead. Ask what each option requires from the venue, the co-op in formation and the participant. Compare supervision, cost, access and risk. Record the option that fits now and what needs further agreement.","captureNotes":"Walk through Formation and participation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Close the formation discussion with a clear next step","body":"Write the current status, the authorised contact for each party and the specific next action. If the venue wants a hiring enquiry, start a role brief. If a training trial fits, name the trainer and a safe assignment. If the matter needs an adopted cooperative decision, keep it open through the formation process. Ask the people affected how they would know the arrangement was working. Agreement about a proposal is separate from permission to share staff or candidate details.\n\nRead the Ready SETCO participation route | https://ready-setco.auraofintelligence.workers.dev/members.html","captureNotes":"Walk through Members and governance with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-employer-founding' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Compare co-op participation, hiring and offering a service. Prepare a role Ready SETCO can help review and discuss with potential workers.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose the business route and describe the role","body":"Ready SETCO is the proposed Ready Sustainable Employment and Training Cooperative on Minjerribah / North Stradbroke Island. A business can discuss possible future membership, ask about filling a real job or propose a service or placement. Start with the result you want and name the person authorised to speak for the business. For a job, the discussion needs the actual employer, worksite, duties, pay basis, roster, start date, supervisor and any access requirements or employer-provided arrangements. Ready SETCO can help organise those facts and clarify what needs checking before an introduction. Membership goes through the applicable admission process once it exists.\n\nRead about participation and membership | https://ready-setco.auraofintelligence.workers.dev/members.html\nEnquire about a business need | https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title","captureNotes":"Use the public membership page and an example employer enquiry. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[1]', json('{"title":"Prepare the brief for a fair introduction","body":"A workable role brief identifies who hires and supervises, where the work takes place, tasks, pay terms, roster, equipment and what support can be offered. Specify only checks that matter to the job. If an introduction is arranged, each person agrees what is shared and with which employer. Discuss whether someone needs training, an adjusted start or a different arrangement. Keep the vacancy status and a response date visible."}'),
    '$[2]', json('{"title":"Follow the route that fits the business decision","body":"For hiring, work with Ready SETCO on the role brief, factual checks and an agreed introduction. For a hosted skills session, confirm the learning goal, supervision, cost, insurance and accessibility. For a service or resource offer, discuss scope, costs, control, and continuation or exit. For cooperative membership, check formation status and the applicable application and approval procedure. The same business can pursue more than one route, with a separate decision and record for each.","captureNotes":"Walk through Member information and business participation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Check the agreement after the first use","body":"Follow up after the first hire, introduction or session. Ask the worker or learner and the supervisor whether the arrangements worked. Recheck changed duties or hours and act on a concern through the agreed contact. Keep hiring, training and membership records with the responsible organisation. If a different purpose needs someone’s information, arrange permission specifically. Keep the next review and responsibility clear.","captureNotes":"Walk through Membership and service follow-up with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-employer-onboarding' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Turn a funding agreement into a delivery, evidence and reporting plan that someone else can pick up.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Set up delivery from the signed agreement","body":"Ready SETCO supports local project teams with scopes, evidence and handovers. This course starts when a funder and recipient have an actual agreement or when a group is rehearsing one. Open the signed agreement and approved budget. Write down the outcomes, eligible costs, dates, proof required and the person authorised to ask the funder for a change. Ask each task lead what support they need to gather useful evidence without collecting unnecessary details from participants.\n\nUse the grant delivery roadmap | https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html","captureNotes":"Capture a fictional budget and milestone register with no real invoices or banking details. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The delivery team has a draft budget and a different budget attached to a signed funding agreement. Which starts the checklist?","choices":[{"id":"a","text":"Use the working file with more detail without reconciling it."},{"id":"b","text":"Use the agreement and approved budget, and record any variation through the proper authority."},{"id":"c","text":"Split spending between the two budgets."}],"correct_choice_id":"b","explanation":"The agreed budget sets the working basis until a variation is authorised.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The project owner is away and a task lead cannot collect the evidence they were assigned. What is useful?","choices":[{"id":"a","text":"Wait until acquittal and make up an estimate."},{"id":"b","text":"Ask participants to send sensitive personal details to everyone."},{"id":"c","text":"Record the gap and arrange the right support or owner before the deadline."}],"correct_choice_id":"c","explanation":"Early help keeps reporting usable without unnecessary collection.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html"]}]}'),
    '$[1]', json('{"title":"Set the first checks with the people delivering the work","body":"Use the funding agreement to schedule a short check with the task and cost owners before spending or booking. Agree what receipt, activity or outcome evidence each person can collect. Work out how participant feedback and unresolved barriers will reach the delivery lead. Schedule a progress review well before the acquittal deadline.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved variation moved a milestone. What do you report?","choices":[{"id":"a","text":"Only the new date with no reference to the agreement."},{"id":"b","text":"Only the original date and omit the reasons for differences."},{"id":"c","text":"The original and revised milestone, evidence of approval and what was actually delivered."}],"correct_choice_id":"c","explanation":"A complete evidence trail explains the change and its result.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A major cost changes during delivery. What should you check first?","choices":[{"id":"a","text":"Only the total funds remaining"},{"id":"b","text":"The funding agreement and the authorised change process"}],"correct_choice_id":"b","explanation":"A change can affect which costs or activities are authorised.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Close, acquit and preserve records","body":"Reconcile actual against approved costs and collect the evidence relevant to output and outcomes. Identify changes or unspent funds and follow the agreement. Have the right person verify the report, lodge through the named route and retain receipts or confirmation and required evidence through the agreed period. Handover open correspondence and checks to the operator or next officer.\n\nKeep the verified acquittal, approval and lodgement or follow-up, and retention owner in the authorised record.\n\nComplete a short handover the people doing the work can use. Record who will handle any final funder questions and what the participants say should be improved in the next round.","captureNotes":"Walk through Delivery and grant reporting with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the verified acquittal, approval and lodgement or follow-up, and retention owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A final report is drafted before a missing invoice and venue approval have been verified. What is responsible?","choices":[{"id":"a","text":"Flag the gaps, get the appropriate checks or advice and accurately disclose any issue before authorised lodgement."},{"id":"b","text":"Submit the report as fully closed because the event was delivered."}],"correct_choice_id":"a","explanation":"The operating record needs the verified acquittal, approval and lodgement or follow-up, and retention owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"an event announcement and unchecked actuals"},{"id":"b","text":"the verified acquittal, approval and lodgement or follow-up, and retention owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-grant-delivery' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Turn a community need into a grant application with an eligible applicant, people who can deliver, a defensible budget and a clear approval to submit.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find an applicant and a programme that fits","body":"Ready SETCO helps local groups prepare useful projects and identify the checks a funding application needs. Start with the issue, people affected and organisation that could take responsibility. Open Grants and find the current programme and guide. Read eligibility, eligible costs, dates, required permission and who reports after funding. Record the guide edition and the applicant''s signing authority. A project can then go forward, be reshaped or be held for a better round. A club, group or proposed co-op needs its own authority before taking on obligations.\n\nOpen the grant roadmap | https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html","captureNotes":"Show the Ready SETCO Grants page and a fictional grant outline. Confirm any external round details at recording time. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A good community idea has no group able to hold the grant. What is the next step?","choices":[{"id":"a","text":"Use a partner''s name without agreement."},{"id":"b","text":"Discuss an eligible applicant or partner and who would approve, deliver and report before submitting."},{"id":"c","text":"Assume every proposed co-op can submit now."}],"correct_choice_id":"b","explanation":"The funder needs a real applicant able to take responsibility.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Which information makes a decision to apply easier?","choices":[{"id":"a","text":"A list of grants with no closing dates."},{"id":"b","text":"A promised outcome without people or costs."},{"id":"c","text":"The current guide, actual deadline, fit, responsible applicant and evidence still needed."}],"correct_choice_id":"c","explanation":"A dated decision lets the right people decide whether to apply or look for another round.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/grant-roadmap.html"]}]}'),
    '$[1]', json('{"title":"Choose whether to proceed with this round","body":"Give the proposed applicant a short decision note with the deadline, funding fit, dates, permissions and what the project can actually deliver. Ask community users or partners whether the outcome is useful and what could prevent participation. If the current round is a poor fit, adapt scope or note a better programme. If it fits, get agreement on who can approve the application and who will write, check and submit it.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One activity cost is estimated and another is quoted. What goes in the budget?","choices":[{"id":"a","text":"Both as confirmed costs because a total is already needed."},{"id":"b","text":"Both as separate lines with their evidence status and a check for the estimate."},{"id":"c","text":"Only the quoted line and an unexplained buffer in the total."}],"correct_choice_id":"b","explanation":"Clear status makes the budget reviewable and the uncertainty visible.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An unconfirmed sponsorship is included in the budget. How should it appear?","choices":[{"id":"a","text":"As proposed with an owner to confirm it"},{"id":"b","text":"As committed income"}],"correct_choice_id":"a","explanation":"Budget reviewers need the funding status to judge whether the plan is viable.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Review, submit and hand over the application","body":"Have the right people compare the draft against every criterion and verify approvals, claims, figures, documents and audience. Confirm the final version and authorised signatory before lodgement and save the actual receipt. Give the next person current status, decisions, deadlines and what would have to change if funding is declined or awarded with conditions.\n\nKeep the lodged version, authority, receipt and who checks decisions or conditions in the authorised record.\n\nBefore submitting, ask the applicant to confirm the final version and owner for any funder questions. Keep the receipt and source pack with them. If the round is unsuitable, share a clear reason and the next viable route.","captureNotes":"Walk through Grant application and closing checklist with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the lodged version, authority, receipt and who checks decisions or conditions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The draft is complete but the approved signatory and delivery evidence are unconfirmed. What is the next step?","choices":[{"id":"a","text":"Submit and assume the email acknowledgement confirms all the missing information."},{"id":"b","text":"Keep it pending, resolve both checks and record the authorised final submission."}],"correct_choice_id":"b","explanation":"The operating record needs the lodged version, authority, receipt and who checks decisions or conditions. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the lodged version, authority, receipt and who checks decisions or conditions"},{"id":"b","text":"a draft PDF and no record of actual lodgement"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-grant-writing' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Use Ready SETCO to describe the work you want, compare an actual offer and put pay, duties, access needs and next steps in writing.',
  title='Find and assess local paid work',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Send a useful paid-work enquiry","body":"Ready SETCO is the Ready Sustainable Employment and Training Cooperative proposal on Minjerribah / North Stradbroke Island. Its work service brings together local work enquiries, employer needs and ways to build skills. In Take part, select Paid work and explain the kind of work, availability and any practical limits such as transport, hours or access. Describe what would help, such as a supervised first shift or a licence refresher. Keep identity evidence private and save the enquiry reference. A specific role can be explored when the work is confirmed with an employer.\n\nExplore paid work and training | https://ready-setco.auraofintelligence.workers.dev/jobs.html\nSend a paid-work enquiry | https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title","captureNotes":"Use a fictional Learning & work profile in an authorised test account. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A person needs an early finish to catch the ferry. What goes into the paid work enquiry?","choices":[{"id":"a","text":"Leave it until induction to avoid losing options."},{"id":"b","text":"Give their actual availability and latest workable finish time alongside the kind of work sought."},{"id":"c","text":"Send personal identity records to prove the availability."}],"correct_choice_id":"b","explanation":"An offer can only be compared with the person''s needs if the team knows when the shifts can work.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html","https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A worker has done venue setup and wants to learn sound. What can Ready SETCO usefully follow up?","choices":[{"id":"a","text":"An automatic sound licence based on interest."},{"id":"b","text":"Unpaid work that fills a paid vacancy."},{"id":"c","text":"Actual setup roles, supported sound training and who could supervise a first task."}],"correct_choice_id":"c","explanation":"The work and skills routes can complement each other when responsibilities and terms are clear.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html","https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title"]}]}'),
    '$[1]', json('{"title":"Compare the offer with your needs","body":"Ask Ready SETCO to help clarify a real offer. The comparison needs the actual employer and supervisor, site, tasks, pay basis, days and shift times, and any licence or supervised training required. Include the last bus or ferry if it affects a shift, what an adjustment would make possible, and which costs or equipment are provided. Record what the employer confirmed, what is open and who can answer. If the work is unsuitable, ask about another roster, role or skills route.\n\nCheck minimum pay and working conditions | https://www.fairwork.gov.au/pay-and-wages/minimum-wages","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two organisations are named on a job idea, and neither is identified as the employer. What do you ask?","choices":[{"id":"a","text":"Who actually employs and supervises, what terms apply and how they are agreed."},{"id":"b","text":"Which one designed the form because that company must be the employer."},{"id":"c","text":"Which one is the largest and whether it can send a general pay schedule."}],"correct_choice_id":"a","explanation":"The actual employer and supervisor need to be clear.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which detail should be clear before agreeing to a role?","choices":[{"id":"a","text":"The actual employer, duties, arrangements and supervisor"},{"id":"b","text":"Only the name of a project"}],"correct_choice_id":"a","explanation":"The actual role determines what you and the employer need to agree.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    '$[3]', json('{"title":"Arrange only the relevant checks","body":"Agree with the employer or authorised reviewer what evidence this particular role requires and how it will be handled. In the member portal, Learning & work lets you save a private profile and request evidence review. An actual check may need a separate approved process. A reviewed claim needs the date, scope and status. Before an employer introduction, agree the named recipient and what can be shared. Ask which part of the work can be practised or learned safely while an agreed check is pending.\n\nOpen Learning & work in the member portal | https://ready-setco.auraofintelligence.workers.dev/portal.html","captureNotes":"Walk through Learning and work profile and authorised employer process with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the scoped check, responsible recipient and agreed records using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A notice asks for a passport and licence photograph in a public comment. What do you do?","choices":[{"id":"a","text":"Ask for the authorised private process for only the checks the role requires."},{"id":"b","text":"Post the documents and delete the comment after the employer responds."}],"correct_choice_id":"a","explanation":"The operating record needs the scoped check, responsible recipient and agreed records. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a public attachment with unneeded identifying data"},{"id":"b","text":"the scoped check, responsible recipient and agreed records"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Close the first work cycle and decide what comes next","body":"Check actual hours and pay against the agreement, return equipment and give the supervisor the handover. Keep your agreement, payslips and a record of any discrepancy. Agree a date for the employer to correct it and ask Fair Work for help if it is unresolved. If the role did not meet your goals or needs, tell Ready SETCO which part failed and ask for a practical alternative. Agree separately whether a checked reference or training record can be shared.\n\nFind Fair Work help | https://www.fairwork.gov.au/find-help-for/visa-holders-migrants\n\nLeave the worker and employer with the agreed next action, a contact and a date. A good introduction includes honest terms and practical support agreed by both sides.","captureNotes":"Walk through Employment records and supervisor with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include your agreed terms, actual records, discrepancies and follow-up contact using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A payslip or work record does not match your hours. How should it be followed up?","choices":[{"id":"a","text":"Compare the evidence and raise it through the authorised employer or official advice process."},{"id":"b","text":"Discard your record and accept the employer’s total because it was issued formally."}],"correct_choice_id":"a","explanation":"The operating record needs your agreed terms, actual records, discrepancies and follow-up contact. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a self-written total without supporting shift or pay evidence"},{"id":"b","text":"your agreed terms, actual records, discrepancies and follow-up contact"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional work enquiry and employer offer. Show the job goal, availability and travel or access limits, then compare the offer with the enquiry. Prepare a written role note confirming employer, duties, site, pay basis, shifts and supervision, and show a safe way to handle one required skills or work-rights check. Explain who owns an unresolved item, what Ready SETCO can follow up and one alternative if the role cannot proceed. The reviewer checks the record shows facts, consent, a workable first shift and a useful handover.',
  edit_version=edit_version+1
WHERE course_id='training-local-work' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the right Ready SETCO route for paid work, training, volunteering, a project or helping form the co-op, and know what happens when you use it.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose what you want to resolve","body":"Ready SETCO stands for Ready Sustainable Employment and Training Cooperative. It is forming on Minjerribah / North Stradbroke Island, with Strange But True as the initial operator. Start at Training & work for work or skills, Events for activities, Grants for project funding, or Members for formation and decisions. Take part is the public enquiry form. The member portal is the signed-in place for private profile information and courses made available to a group. Choose the route that fits the outcome you want and use that page''s specific enquiry or contact. A person can explore the public site before opening an account.\n\nExplore Ready SETCO''s work and training routes | https://ready-setco.auraofintelligence.workers.dev/jobs.html\nOpen the private portal | https://ready-setco.auraofintelligence.workers.dev/portal.html","captureNotes":"Capture the public home and sample lesson. Use the public pages in the recording. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[1]', json('{"title":"Use the route that fits the task","body":"For a paid job enquiry use Take part and select Paid work or Working holiday work. For a project or hosting offer name the activity and the person who can discuss it. For private courses open the portal and look for Learning & work and Your courses. Access depends on the group and what it has released. Ask the course contact or organiser if an expected course is missing.\n\nGo to Take part | https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title"}'),
    '$[3]', json('{"title":"See what Ready SETCO checks and follows through","body":"Ready SETCO coordinates enquiries, checks and handovers across employers, training leads and local groups. A useful handover shows what was confirmed, who checked it, which person is responsible and when to follow up. Where a requirement applies, use the relevant authority or source. Better support can mean clearer terms, a readable update, an accessible session or a different role that fits. Ask what will be shared and with whom before giving permission. Each group or employer still makes the decisions it is responsible for. That is how we make it easier for people to learn, work and help each other with care.","captureNotes":"Walk through Take part and Member portal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Follow up with a clear reference","body":"Keep the enquiry reference, activity name or map suggestion ID. If the path is open, confirm the next action, who handles it and when to check again. If the proposal or work is still being developed, ask what is available now, such as a confirmed visit, another role, an introduction to a learning lead or permission to send a suitable proposal. Help someone new by giving them the relevant route and the current status in plain language.","captureNotes":"Walk through Public contact, map or portal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-site-tour' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find a supervised community task that fits your time and access needs, agree the brief and close the shift with a usable handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find an agreed volunteer task","body":"Ready SETCO''s community work connects local groups, people offering time and people learning a skill. Start with a confirmed organiser and an activity that interests you. A useful shift offer specifies date, place, task, hours, named lead, and any training, access or safeguarding arrangements. If you have a contact but no confirmed task, ask the lead where your help would fit or send a volunteering enquiry. Agree any voluntary contribution record separately from paid work. A suitable shift leaves enough time to brief, help and hand over safely.\n\nFind a volunteering route | https://ready-setco.auraofintelligence.workers.dev/join.html#interest-title\nSee local activities and events | https://ready-setco.auraofintelligence.workers.dev/events.html","captureNotes":"Use a fictional event run sheet and show a sample shift briefing. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    '$[1]', json('{"title":"Check the briefing before starting","body":"Meet the shift lead at check-in. Ask for a quick demonstration and check that the task can be done within your time, access, support and gear needs. Agree what happens if weather or attendance changes and who handles a safety concern. If the job and support do not fit, ask about an adjusted task, a different shift or introductory practice."}'),
    '$[4]', json('{"title":"Finish the shift and leave the next person a useful update","body":"Return equipment, confirm what was done, pass any private concern to the right person and name the owner of unfinished work. If the organiser is trialling a voluntary contribution record, agree the time and what it measures. Ask for useful feedback and whether another shift or skills activity would be suitable.","captureNotes":"Walk through Volunteer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='training-volunteer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Start with the kind of work you''re looking for, ask Ready SETCO to help compare a real local role and leave with a clear next step on pay, logistics, evidence and any specified-work question.',
  title='Find suitable paid work during a working holiday',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Start with the work you want","body":"Ready SETCO stands for Ready Sustainable Employment and Training Cooperative. It is forming on Minjerribah / North Stradbroke Island. Its work service coordinates enquiries, helps unpack employer offers and supports checks before an introduction. Local roles are still being developed.\n\nChoose the outcome that matters for this enquiry: earning income, finding paid work that may count as specified work for a further visa, or gaining experience through a separate training or volunteer opportunity. These routes can run alongside each other. In Take part, choose Working holiday work. The enquiry needs availability, relevant skills, the work sought and any limits that affect a shift, such as ferry times. If specified work matters, say so and note any timing constraint. Use a visa subclass you already know if it is useful to the check. Keep passport numbers, scans and visa documents out of the enquiry. Save the reference. The team can use it to follow up about a suitable role or a check that is still needed.\n\nWorking holiday work on Straddie | https://ready-setco.auraofintelligence.workers.dev/jobs.html#backpacker-work\nSend a working holiday work enquiry | https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title","captureNotes":"Use a fictional offer and participant to demonstrate start with the work you want. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A worker wants paid income now and would prefer specified work if available. What should the enquiry say?","choices":[{"id":"a","text":"Ask the organiser to choose a visa subclass for them."},{"id":"b","text":"Give dates, skills and limits, and ask to compare suitable paid work with roles that may count."},{"id":"c","text":"Send a passport scan and ask for any unpaid shift with a signed letter."}],"correct_choice_id":"b","explanation":"The enquiry starts with the work goal and what makes a role possible. Identity evidence belongs in an appropriate private process.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html#backpacker-work","https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A visitor can work weekdays but cannot catch a ferry after 7 pm. Where should that appear?","choices":[{"id":"a","text":"Only after the first late shift."},{"id":"b","text":"Only in a message to the visa authority."},{"id":"c","text":"In the enquiry and in the shift discussion before accepting an offer."}],"correct_choice_id":"c","explanation":"A role must be workable in practice as well as checkable on paper.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html#backpacker-work","https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title"]}]}'),
    '$[1]', json('{"title":"Review a real offer with Ready SETCO","body":"Start with the employer and the actual work. A useful role description names the employer, worksite and postcode, duties, start date, hours and pay basis, supervisor and who issues payslips. Include transport, accommodation terms or deductions if they matter. Ask Ready SETCO to compare the offer with the request and help clarify missing facts with the employer. Use Confirmed or Needs checking beside each point, with the source and date. An enquiry reference helps the team find the conversation. A confirmed employer can explain the award or pay basis and give the terms in writing before someone commits.\n\nExample: a Goompi / Dunwich café needs someone for morning counter and kitchen shifts. Confirm the actual duties, which venue uses the roster and whether the start fits the ferry. If the shifts moved to a different site, review that site and travel separately.\n\nCheck pay and conditions | https://www.fairwork.gov.au/find-help-for/visa-holders-migrants","captureNotes":"Use a fictional offer and participant to demonstrate review a real offer with ready setco. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A venue lists a Sunday shift and says it will sort out the rate after you arrive. What should happen before accepting?","choices":[{"id":"a","text":"Assume a higher rate because it is a Sunday."},{"id":"b","text":"Accept because Sunday shifts automatically count twice."},{"id":"c","text":"Ask the employer to confirm the pay basis, hours and other terms in writing and check any open point with Ready SETCO."}],"correct_choice_id":"c","explanation":"Pay and the working arrangement need to be understood before the person commits.","source_refs":["https://www.fairwork.gov.au/find-help-for/visa-holders-migrants"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A listing gives a brand name and an island postcode but no worksite. What does Ready SETCO need next?","choices":[{"id":"a","text":"The actual employer, worksite, duties and who pays and supervises the shift."},{"id":"b","text":"A promotional screenshot of the brand."},{"id":"c","text":"A copy of the worker’s passport in the enquiry form."}],"correct_choice_id":"a","explanation":"The role is assessed on the actual arrangement. A general listing is only a lead.","source_refs":["https://www.fairwork.gov.au/find-help-for/visa-holders-migrants"]}]}'),
    '$[2]', json('{"title":"Work out what this role can help with","body":"Keep two separate questions on the role note. First, can the person do this paid work under their current conditions? An authorised work-rights check can use Visa Entitlement Verification Online (VEVO) with permission. Second, does this actual work meet the relevant specified-work settings for a later visa? Ready SETCO can assemble the role facts and point you to the official matched rule. For applicable tourism and hospitality work, 4183 is a listed location. The duties, industry, period and evidence matter as well. Where a question about an individual visa application remains, follow the Home Affairs route or an authorised migration professional.\n\nPlanning ahead? Home Affairs says the 88-day second-visa transition ends 28 February 2027; it moves to 120 days from 1 March 2027 for applicants subject to the requirement. It also sets out registration and invitation changes, with separate UK passport arrangements. Check the note tied to the intended application date before relying on a count.\n\nSee the 417 specified-work rules | https://immi.homeaffairs.gov.au/what-we-do/whm-program/specified-work-conditions/specified-work-417/\nSee the 462 specified-work rules | https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/work-holiday-462/specified-462-work\nCheck registration, application dates and rule changes | https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/new-registration-and-invitation-process-for-second-and-third-whms\nCheck the separate UK passport arrangements | https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/arrangements-uk-passport-holders\nFind authorised immigration assistance | https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview","captureNotes":"Use a fictional offer and participant to demonstrate work out what this role can help with. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A role is paid and the employer can verify work rights. What separate check still matters if specified work is a goal?","choices":[{"id":"a","text":"Review the actual duties, industry, site, dates and evidence against the applicable specified-work rules."},{"id":"b","text":"Count every paid role listed above a minimum rate."},{"id":"c","text":"Treat a VEVO result as the specified-work decision."}],"correct_choice_id":"a","explanation":"Work rights relate to taking the job. A later specified-work claim has a different set of requirements.","source_refs":["https://immi.homeaffairs.gov.au/what-we-do/whm-program/specified-work-conditions/specified-work-417/","https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/work-holiday-462/specified-462-work","https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/new-registration-and-invitation-process-for-second-and-third-whms","https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/arrangements-uk-passport-holders","https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"An employer says an event job counts because it is on Straddie. How can the team help?","choices":[{"id":"a","text":"Mark it confirmed using the postcode only."},{"id":"b","text":"Record the real duties and location, compare the applicable official criteria and refer an unresolved visa question appropriately."},{"id":"c","text":"Ask the worker to count it now and check after applying."}],"correct_choice_id":"b","explanation":"A listed location alone cannot tell the worker whether their specific job and work period qualify.","source_refs":["https://immi.homeaffairs.gov.au/what-we-do/whm-program/specified-work-conditions/specified-work-417/","https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/work-holiday-462/specified-462-work","https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/new-registration-and-invitation-process-for-second-and-third-whms","https://immi.homeaffairs.gov.au/what-we-do/whm-program/latest-news/arrangements-uk-passport-holders","https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview"]}]}'),
    '$[3]', json('{"title":"Choose the next best route","body":"Bring the options back to your goal. Paid work that may count can go forward for the necessary role and work-rights checks. A properly paid job that does not fit specified-work rules may still be useful for income and experience. Ask Ready SETCO for a different role, another location, a more workable roster or a skills route if the local offer is unsuitable. Discuss a community volunteering option separately with the organiser, including its purpose, support and hours. Paid tourism or hospitality duties are paid work. A voluntary shift or C-Hour record cannot replace those wages.\n\nBefore an introduction, ask what information would be shared, with whom and why. Share only the agreed fields. While a role is being explored, keep the reference so the team can follow up; ask for alternatives rather than making travel plans around an unconfirmed start.\n\nSee paid work, training and volunteering options | https://ready-setco.auraofintelligence.workers.dev/jobs.html\nFind worker support | https://www.fairwork.gov.au/find-help-for/visa-holders-migrants","captureNotes":"Use a fictional offer and participant to demonstrate choose the next best route. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Work that fits the roster is ordinary paid work and the specified-work question remains unresolved. What are the useful options?","choices":[{"id":"a","text":"Treat the job as specified work until someone says otherwise."},{"id":"b","text":"Compare the job as paid work and ask for a separate route if specified work remains the goal."},{"id":"c","text":"Relabel a volunteer shift at the venue to fill the gap."}],"correct_choice_id":"b","explanation":"A clear separation gives the worker a choice about income and a different route for specified work.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html","https://www.fairwork.gov.au/find-help-for/visa-holders-migrants"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A host offers unpaid reception shifts and a letter saying they count as paid tourism work. What should the team do?","choices":[{"id":"a","text":"Accept the letter instead of pay records."},{"id":"b","text":"List it as training regardless of the duties."},{"id":"c","text":"Hold that option, ask for the proper paid arrangement and point the worker to Fair Work if needed."}],"correct_choice_id":"c","explanation":"The actual work arrangement matters. A letter does not replace wages or the employer’s obligations.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/jobs.html","https://www.fairwork.gov.au/find-help-for/visa-holders-migrants"]}]}'),
    '$[4]', json('{"title":"Agree the shift and recheck changes","body":"Agree who employs you, what you will do, where, when and for how much before starting. Ask who handles onboarding, safety and an adjustment, and where to raise a problem. For a confirmed role, use private evidence review in Learning & work if an authorised check is arranged. A worksite, duties, pay basis, employer or dates change can affect both the offer and the evidence planned for a further visa. Tell the employer and Ready SETCO which fact changed. Ask them to update the role note and keep confirmed and pending points visible. Agree whether to proceed, hold the changed arrangement or explore a different option. Check any visa-specific condition through the official route.\n\nOpen Learning & work in the portal | https://ready-setco.auraofintelligence.workers.dev/portal.html\nCheck visa details and conditions through VEVO | https://immi.homeaffairs.gov.au/visas/already-have-a-visa/check-visa-details-and-conditions/check-conditions-online","captureNotes":"Use a fictional offer and participant to demonstrate agree the shift and recheck changes. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"An owner moves you from the confirmed venue to a job at another property. What do you do?","choices":[{"id":"a","text":"Keep logging the original venue because it was approved first."},{"id":"b","text":"Treat the relocation as a pay-only issue."},{"id":"c","text":"Ask for the new duties, site and arrangement in writing and recheck open issues before relying on the change."}],"correct_choice_id":"c","explanation":"The record needs to describe the work that actually takes place.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/portal.html","https://immi.homeaffairs.gov.au/visas/already-have-a-visa/check-visa-details-and-conditions/check-conditions-online"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A team wants to introduce you to a different employer. What should be agreed?","choices":[{"id":"a","text":"Which employer, role and minimum details you agree may be passed on."},{"id":"b","text":"Give the new employer access to all your identity and training records."},{"id":"c","text":"Treat a previous enquiry as permission to send the whole profile."}],"correct_choice_id":"a","explanation":"Agreement about one introduction is specific to its purpose and recipient.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/portal.html","https://immi.homeaffairs.gov.au/visas/already-have-a-visa/check-visa-details-and-conditions/check-conditions-online"]}]}'),
    '$[5]', json('{"title":"Keep proof and get help if something changes","body":"Save your work agreement, actual roster or shift log, payslips, payment and worksite dates. Check each pay cycle that the record reflects the hours and duties worked. For a specified-work goal, use the official counting method and keep the documents the current process requires. Seek a correction early if an employer record is wrong. Give Ready SETCO the role and enquiry reference if you want help following up. Fair Work Ombudsman can explain workplace rights and help with pay or conditions. Home Affairs and authorised immigration professionals handle visa-specific issues. If a role falls through, return to the work goal and ask what other paid or training options can be explored.\n\nA good handover leaves the worker with the decision so far, the source checked, the person doing the next check and when to follow up.\n\nGet Fair Work help for visa holders | https://www.fairwork.gov.au/find-help-for/visa-holders-migrants\nFind authorised visa assistance | https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview\nFollow up about a Ready SETCO work route | https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title","captureNotes":"Use a fictional offer and participant to demonstrate keep proof and get help if something changes. Keep identity records and actual case details out of the capture.","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A payslip misses a shift. What is the practical next step?","choices":[{"id":"a","text":"Keep the roster and payment evidence, ask the employer to correct it and seek Fair Work help if it is unresolved."},{"id":"b","text":"Change your own hours log to match the payslip."},{"id":"c","text":"Wait until the final visa application to raise it."}],"correct_choice_id":"a","explanation":"A dated correction request and corroborating records make the pay issue easier to resolve.","source_refs":["https://www.fairwork.gov.au/find-help-for/visa-holders-migrants","https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview","https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"No local role is confirmed by the date you can arrive. What can the enquiry handover still do?","choices":[{"id":"a","text":"Tell the worker to travel because applying reserves a shift."},{"id":"b","text":"Keep your work goal and limits clear, note what was checked and ask about other employers, locations or training options."},{"id":"c","text":"Treat the original enquiry reference as proof of employment."}],"correct_choice_id":"b","explanation":"A useful follow-up gives a concrete alternative and an honest status.","source_refs":["https://www.fairwork.gov.au/find-help-for/visa-holders-migrants","https://immi.homeaffairs.gov.au/help-support/who-can-help-with-your-application/overview","https://ready-setco.auraofintelligence.workers.dev/join.html?interest=working_holiday#interest-title"]}]}')
  ),
  practical='Use a fictional person and two role offers. One seeks paid work that may count as specified work and depends on the last ferry. The other could be ordinary paid work. Prepare the enquiry, then a role comparison showing the employer, worksite and postcode, duties, pay, roster, transport, evidence owner, confirmed facts and open questions. Show the follow-up you would ask Ready SETCO to coordinate and what you would do if the site or duties changed. Show a separate training or community option if neither job fits. The assessor checks that every conclusion has its own evidence, the worker controls sharing, and any unresolved visa matter reaches the appropriate authority.',
  edit_version=edit_version+1
WHERE course_id='training-working-holiday' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Work within the Secretary’s delegation, support meeting and archive tasks and give back a clear record of work still open.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree the prospective deputy remit","body":"Sandy Sports is in formation. Ask the Secretary to agree what the Assistant Secretary covers and for how long. In the committee room, find the correct notice, agenda and minutes record. For Rule 4B duties, agree who will operate, test, verify and hand over the full meeting recording.\n\nRead the actual status of the proposed office and agree what the Secretary can assign now. Identify which tasks you can prepare, which you will handle under documented cover and which require a named approval or restricted role. Check access in the real authorised role before any live use. Keep a joint list of deadlines, unresolved work and the contact to escalate to before taking responsibility for a public notice or member record.\n\nKeep the delegated work, authority, backup contact and review date in the authorised record.\n\nOpen Sandy’s meeting recording and archive workflow | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the delegated work, authority, backup contact and review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Someone sees the Assistant Secretary label and asks for an immediate formal approval. What do you check?","choices":[{"id":"a","text":"Approve in the same way as the Secretary because the role name indicates deputy access."},{"id":"b","text":"Check actual authority, delegated scope and the current formation or approval setting."}],"correct_choice_id":"b","explanation":"The operating record needs the delegated work, authority, backup contact and review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the delegated work, authority, backup contact and review date"},{"id":"b","text":"the role label and a message that cover has begun"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[7]', json('{"title":"Hand over both recurring work and cover exceptions","body":"Show the next deputy and Secretary the current joint task list, next papers and notices, returned sheets, issue version, delivery and member follow-ups. List restricted referrals by authorised reference. Recheck access and the scope of temporary cover. Leave named owners and dates for unresolved work and arrange a short first-week walkthrough.\n\nKeep the dated joint list, running documents, referral owners, cover and next check in the authorised record.\n\nReport what is ready, which link or decision is unresolved and who should look at it. Return the meeting and restricted references through the Secretary.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the dated joint list, running documents, referral owners, cover and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming deputy can see officer work but a restricted case remains with the Secretary. What should you transfer?","choices":[{"id":"a","text":"The next action and responsible role through authorised means, with access limited to their approved scope."},{"id":"b","text":"Copy the full case into the general handover so both can access it."}],"correct_choice_id":"a","explanation":"The operating record needs the dated joint list, running documents, referral owners, cover and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a broad instruction to cover the role without deadlines"},{"id":"b","text":"the dated joint list, running documents, referral owners, cover and next check"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=4 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Trace a proposal from an agenda item to a decision, delegated work and an accessible record, using Sandy’s actual role boundaries.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Understand the prospective role and decision limits","body":"Sandy Sports is in formation. Open How it works for the desk map and access table, then check your confirmed or proposed office with the organiser. Use a nominated item to trace who may discuss, decide, publish and take follow-up. Use the current rules and meeting status before describing a result as adopted.\n\nConfirm the status of the club and your proposed role. Read the current rules or draft, shared officer responsibilities and actual delegated work before speaking or committing for the group. Check which responsibilities are collective and which belong to the operator, Secretary, Treasurer or safeguarding lead. Use the individual role and authorised tools assigned.\n\nKeep the office scope, referral contact, decision source and next action in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Committee room and Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the office scope, referral contact, decision source and next action using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A committee planning note asks you to promise a refund to an applicant. What do you check?","choices":[{"id":"a","text":"Who holds the authority and payment record and whether the proposed action has been approved."},{"id":"b","text":"Whether the applicant originally contacted you through a private message."}],"correct_choice_id":"a","explanation":"The operating record needs the office scope, referral contact, decision source and next action. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a public note listing who offered to assist"},{"id":"b","text":"the office scope, referral contact, decision source and next action"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Debrief and hand your work to the next person","body":"Record the result or lessons from the activity, what actually happened, any exception still open and what needs a responsible decision. Provide the current and previous records by authorised reference. Make sure outgoing or incoming access and property are dealt with by the appropriate owners. Agree the next check, especially if the role is still prospective.\n\nKeep a dated handover of decisions, evidence, next owners and restrictions in the authorised record.\n\nAfter a decision, ask who needs the update in what form, and what would help the person given the action deliver it. Keep the action owner and next review visible.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include a dated handover of decisions, evidence, next owners and restrictions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A follow-up is postponed after someone changes roles. What should the outgoing person leave?","choices":[{"id":"a","text":"A general note for the next committee meeting to sort out."},{"id":"b","text":"The named owner or escalation contact, new date and source decision."}],"correct_choice_id":"b","explanation":"The operating record needs a dated handover of decisions, evidence, next owners and restrictions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a dated handover of decisions, evidence, next owners and restrictions"},{"id":"b","text":"an exported task list with no explanation of outstanding work"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-committee-member' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check whether a site and its equipment can support an agreed activity, and hand over real access, risks and responsibilities.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Establish ownership and the permitted use","body":"Sandy Sports has proposed venues and facility options. Start with an actual request and identify the landholder or person who can approve access. Compare the intended layout and audience with usable space, accessibility, power, storage and equipment. Put approval, remaining questions and setup responsibilities where the crew can find them.\n\nIdentify the owner, administering contact and current status of each possible site. Ask what site activity, duration, capacity or attachment is allowed and which permissions still apply. Keep public map or concept images distinct from a booking. Record when and by whom the conditions were confirmed and who would make or accept any commitment. Look for conditions relating to restoration, cleanup and renewal.\n\nKeep the site source, responsible authority, allowed use and unresolved decisions in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the site source, responsible authority, allowed use and unresolved decisions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A council map labels an area open space. What confirms the proposed club activity can go ahead there?","choices":[{"id":"a","text":"The site''s public access on the map and a suitable rough layout."},{"id":"b","text":"The responsible site authority and documented use conditions for the intended event."}],"correct_choice_id":"b","explanation":"The operating record needs the site source, responsible authority, allowed use and unresolved decisions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the site source, responsible authority, allowed use and unresolved decisions"},{"id":"b","text":"a map marker labelled confirmed venue"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Hand over facilities readiness and risks","body":"Give the next lead the latest confirmed site permissions, draft options, calendar, gear register and owners, costs, maintenance, unsafe or held items and due dates. Show how to check conditions with site owners and who holds equipment custody. Review staff access and transfer of keys through authorised processes. Agree next decision and post-event review dates.\n\nKeep the facilities index, actual authorities, equipment and open checks with owners in the authorised record.\n\nReturn the venue and confirm the condition with the person responsible. Hand over faults, access constraints and the date when the next crew can rely on the space.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the facilities index, actual authorities, equipment and open checks with owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming facilities lead gets the floor plan but lacks the accepted site conditions. What do you do?","choices":[{"id":"a","text":"Keep the handover item open and name who will obtain the current authority and use restrictions."},{"id":"b","text":"Use the designer’s plan as the basis to schedule site use."}],"correct_choice_id":"a","explanation":"The operating record needs the facilities index, actual authorities, equipment and open checks with owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a map pack and calendar with approvals inferred"},{"id":"b","text":"the facilities index, actual authorities, equipment and open checks with owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-facilities-lead' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Plan a film activity that makers, members and viewers can take part in safely, and hand off any publication or public meeting coverage.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Scope the film activity and authorise the next step","body":"Sandy Film Club is part of the developing Sandy Sports club. Start with one proposed screening, shoot or workshop and confirm the actual organiser and venue. Use the committee’s film work area to name the lead, crew, audience, licence, funding and safeguarding. For news or a public stream, bring in the authorised editorial officer and agree the media handoff.\n\nDescribe the audience and aim and choose whether it is a screening, workshop or production. Agree the deliverable, likely space, gear, crew, cost and responsible leads. Identify which permissions, funding and date decisions are still needed. Keep the project listed at the status actually agreed and coordinate with sports, facilities and partners before promising capacity.\n\nKeep the event scope, people, budget assumptions and open authority in the authorised record.\n\nOpen Sandy Film Club | https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the event scope, people, budget assumptions and open authority using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The team has a venue concept and a popular film in mind. What does the lead record?","choices":[{"id":"a","text":"A proposed format and pending venue, rights, budget and crew decisions."},{"id":"b","text":"A planned public screening ready to advertise while checks continue."}],"correct_choice_id":"a","explanation":"The operating record needs the event scope, people, budget assumptions and open authority. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a film title and draft event graphic"},{"id":"b","text":"the event scope, people, budget assumptions and open authority"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[7]', json('{"title":"Connect production to Island News and live coverage","body":"Send Island News stories through the Film Club member form with their approved scope, credit and sources. An authorised editor reviews the story and hands a permitted copy to the network steward. For an approved Sandy public meeting, assign a crew to run the external encoder, audio, continuous local recording and viewer check. The Secretary is responsible, the Secretary or Assistant Secretary makes the recording, and the officers with Members and publishing access under Schedule 1 approve public streams. Film Club crew may operate the equipment. Plan for full video and audio from opening to close and the complete public replay on Island News and Live. Give the Secretary the original files and verified links for archive and transcription. Follow separate event permissions and the network steward’s review when sharing externally.\n\nReview the venue check and participation feedback with the crew. Give the next lead the rights, costs, source record and named approval still needed for each next use.","captureNotes":"Show a fictional crew sheet, the Schedule 1 approval handoff and the complete recording handoff to the Secretary. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Film Club producer and camera operator are ready, but there is no signed-in editor authorised to manage the news listing. What next?","choices":[{"id":"a","text":"Arrange an authorised publisher and agree the release plan before going publicly live."},{"id":"b","text":"Ask the camera operator to use the editor’s account."},{"id":"c","text":"Publish it on an unrelated personal channel and notify the club later."}],"correct_choice_id":"a","explanation":"The producer runs capture and makes sure the editor is available for the distinct publishing decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You have a highlight reel and a complete Sandy public forum recording. Which goes to the official replay and archive?","choices":[{"id":"a","text":"Publish the highlights as the official replay and discard the full recording."},{"id":"b","text":"Use the complete recording for the public replay and give the unedited original video and audio to the Secretary for the archive."},{"id":"c","text":"Send only the transcript and ask the steward to create a new master."}],"correct_choice_id":"b","explanation":"Rule 4B keeps the full recording and its public replay. A highlight is a separate production.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-film-lead' AND revision=1 AND state='draft' AND edit_version=4 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find your lane in Sandy Film Club and use its practical routes for sessions, kit, volunteering or submitting a story.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find your way into Film Club","body":"Sandy Film Club covers screenings, production, sports coverage and learning. Find public information on the Film Club page. With current member access, open My Membership and choose Film club to find the lane choices, the kit shelf and the story route. Confirm a session and its contact before making arrangements.\n\nOpen Sandy Film Club | https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","captureNotes":"Capture the public page and show the four lane cards in a synthetic My Membership account. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"}'),
    '$[4]', json('{"title":"Join a sport crew or try a workshop","body":"Agree a small task, call time, point of contact and handoff with the crew lead. Ask what may be filmed and how to opt out, and where to deliver a labelled copy. A public broadcast needs a named crew and a separate publishing decision. After the activity, return kit, send permitted files to the lead and ask what to practise next.\n\nUse the lane that fits the next action. Ask the named lead what preparation, equipment or training a session needs, and check when someone will reply.","captureNotes":"Walk through a fictional sport crew brief and show the link to Island News. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-film-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Confirm what to do before a first club screening, workshop or supported shoot, and know whom to ask about terms and permission.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose how you want to take part","body":"Use the Sandy Film Club public page to find an activity. Ask whether there is a confirmed screening, workshop or supervised production and who is leading it. With member access, the Film club tab also gives routes for Watch, Make, Sport crew or Learn. Agree the time, venue, access and any filming or kit requirements with the session lead.\n\nOpen Sandy Film Club | https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","captureNotes":"Show a public film club concept and fictional workshop listing. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/ Show My Membership, Film club and Island News from a synthetic view. https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"}'),
    '$[1]', json('{"title":"Check the activity and make the visit workable","body":"Identify the confirmed contact and ask about meeting point, venue access, transport, equipment and how changes are communicated. For a first workshop or shoot, ask who will introduce the task and where to find help during the session."}'),
    '$[2]', json('{"title":"Choose a different way to take part if needed","body":"If no suitable place is confirmed, ask about a later screening, a learning session, an accessible time or a supported task using approved material. Use the Film Club member guide when you want to explore the four lanes or the shared kit. Agree with the lead before putting your name down for a new task.\n\nExplore Sandy Film Club | https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","captureNotes":"Walk through Film Club and programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Finish the session and choose a next step","body":"Return equipment, share feedback and ask what may be kept or used in a portfolio. Confirm who receives a concern, how lost items are recorded and how to hear about the next proposed workshop or screening.\n\nAfter the session, ask the lead about one appropriate follow-up such as getting feedback, borrowing equipment with consent or joining a crew rehearsal.","captureNotes":"Walk through Film Club workshop or screening lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-film-participant' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Turn a local idea or offer into a formation proposal with the right contact, visible status and a fair way to follow it up.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find your starting point","body":"Sandy Sports is forming as a proposed club. Start with its public programme and formation information. To propose an activity, describe what it would do, who could take part and which person, location or permission is needed. Use the club’s participation route to ask for the appropriate discussion.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the public Join page and labelled My Membership preview. Use fictional names and no sign-up details. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Review proposals and communications","body":"Check current rules, proposals, dates and approved statements before forwarding them. Ask where to correct your details or change contact preferences. Keep private names and access links within the agreed workflow and raise unclear decisions with the organiser.\n\nReview the draft constitution’s Rule 4B and ask how it would apply at the founding meeting and later AGM. The draft sets out full committee and general meeting recording, permanent member access, notices about recording and public replays when a meeting is public. People standing for office agree through their nomination. Look for which provisions are still proposed and how members can comment before adoption.\n\nRecord what people agreed to explore, who checks it and when you can ask again. Include an access or support improvement suggested by someone who might use the activity.","captureNotes":"Show the Rule 4B workflow beside the draft constitution using a fictional founding meeting notice. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-founding-member' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Follow a Sandy Sports task from the public site or My Membership to the officer who can act and the record that shows what happened.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Three doors into the club","body":"Sandy Sports is in formation. How it works shows the public website, My Membership and the committee room. Use its process map when you need to find an event, take an offer of help forward or check who can decide a matter. Start from the route that applies to you and follow the next named action.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the public three-door map on desktop and mobile. Use a synthetic account only if demonstrating the signed-in view. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html"}'),
    '$[4]', json('{"title":"From committee decisions to ongoing work","body":"Open the meeting and AGM flow. Find who prepares the agenda, how the meeting becomes an approved record, and how follow-up tasks reach officers. Then check the officer access flow for a resolution, invitation and handover. Browse the newsletter, sponsorship and store examples to identify the human decision and the record it leaves. If a handoff stalls, follow the flow to the next actor and share the task reference through the appropriate channel.\n\nFollow Recording and archiving meetings (rule 4B) as a worked example. Find who makes the recording, who signs off a public stream and where a member goes to Watch, Listen or read a Transcript. Committee and general meetings, including the AGM, are recorded in full under the draft rule. Find the complete public meeting replay on Island News and Live and compare that path with the permanent member archive.\n\nPick a process that applies to you, then identify the first action and the person who can take the next step. Save a reference or ask that person for a status update.","captureNotes":"Show the live Rule 4B process flow and a synthetic member archive next to the public replay link. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-how-it-works' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a useful local story, verify the facts and permission, then hand it to the Sandy editor with a way to follow up.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find a reportable local story","body":"Island News is Sandy Sports’ public news and live page. To suggest a news story, use the Film club tab in My Membership when contributor access is available. Start with the actual event or story, audience, date and source. Check what can be photographed, named and shared. The editor needs the written facts and a way to verify permission before making a decision.\n\nChoose a useful local event, game, place activity or community story. Note what happened, who is affected, what people can do next and what needs verification. Get time and place from the organiser and confirm changes against a second appropriate source. Write contributors and source links in your private notes. Ask a reviewer where to take an urgent safeguarding matter rather than putting it in a public pitch.\n\nOpen the Sandy Island News story workflow | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","captureNotes":"Build a story card from two fictional club sources. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Two flyers have different dates for the same event. Which date should you use?","choices":[{"id":"a","text":"Copy both dates as if they are separate sessions."},{"id":"b","text":"Ask the organiser to confirm the authoritative date and timestamp the check."},{"id":"c","text":"Take the date from whichever flyer looks newer."}],"correct_choice_id":"b","explanation":"Resolve the conflicting dates with the organiser before filing.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Someone shares an unverified claim about an identifiable resident. How should you handle it?","choices":[{"id":"a","text":"Publish the claim in a question headline."},{"id":"b","text":"Include it in captions and ask viewers to decide."},{"id":"c","text":"Keep it out of the story and refer it privately if it raises a concern."}],"correct_choice_id":"c","explanation":"An accusation calls for verification and possibly a private reporting channel, rather than amplification.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]}'),
    '$[5]', json('{"title":"Hand over the source files","body":"Give the editor the approved publication file, rights and source references, a contact for corrections and any hold or pending check. Label version, contributor credit and intended audience. Transfer originals only through the agreed restricted channel when needed. Keep your written rundown short enough for someone else to take over tomorrow. Check that a story listed as published links to the reviewed edition.\n\nUse the submission or story reference to follow up on checks, edits or withdrawal. Give the editor the current approved media, source contact and any limits that matter for partner use.","captureNotes":"Create a sample handover manifest with source notes, media version and decisions. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which file should an editor queue for the public version?","choices":[{"id":"a","text":"The oldest raw capture with no permissions record."},{"id":"b","text":"The highest-resolution item regardless of its editorial status."},{"id":"c","text":"The labelled, checked publication cut with its approval scope."}],"correct_choice_id":"c","explanation":"The public artefact needs its own known version and scope.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Your preferred credit and correction contact differ. Where do they go?","choices":[{"id":"a","text":"Use approved public credit and keep the correction contact in the restricted handoff."},{"id":"b","text":"Add both to the public headline."},{"id":"c","text":"Remove all private contact options so corrections have no route."}],"correct_choice_id":"a","explanation":"Keep a useful private correction channel and share only the agreed public credit.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-island-news-contributor' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Review a story or public broadcast against the actual evidence, release the correct edition and follow corrections through each outlet.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Open the queue and know your publishing authority","body":"Island News is Sandy Sports'' news, stream listing and replay page. The committee room’s Island news and live desk holds the working queue. Check editorial and Schedule 1 Members and publishing access, then open a specific story or broadcast. Identify the maker or crew, intended audience and actual supporting permissions before acting.\n\nGo to Committee room, Island news and live. Review items submitted from My Membership. Sandy’s officers can see the queue. The member records office group can act on stories and broadcasts: President or Vice President, Secretary or Assistant Secretary, Treasurer and Webmaster under the site''s current rules. Check your real editorial delegation too, along with conflicts of interest and availability of an alternate. For cases outside your remit, note the deadline and hand the reference to the agreed officer.\n\nOpen Sandy Island News | https://sandy-sports-club.auraofintelligence.workers.dev/news.html","captureNotes":"Show the desk followed by the corresponding access row with fictional records. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A general committee officer sees a story with Publish unavailable. What should they do?","choices":[{"id":"a","text":"Make a public copy of the queue item in a personal account."},{"id":"b","text":"Send the story reference to an authorised editor and flag the deadline."},{"id":"c","text":"Borrow an authorised officer’s password to release it."}],"correct_choice_id":"b","explanation":"Visibility lets the officer coordinate. The decision belongs to someone who can act under the current delegation and permissions.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You are the editor and the story promotes your own business. How can it proceed?","choices":[{"id":"a","text":"Approve it before declaring the interest at the next meeting."},{"id":"b","text":"Ask the contributor to remove your name but decide it yourself."},{"id":"c","text":"Declare the interest and hand the independent editorial decision to an appropriate alternate."}],"correct_choice_id":"c","explanation":"Disclosure and an independent reviewer protect the decision and the record.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]}'),
    '$[5]', json('{"title":"Correct, unpublish and hand over","body":"If an item has wrong information or unsafe content, check its immediate exposure and unpublish where needed. Preserve a private decision trail with version, actor, time and reason. Coordinate a correction or withdrawal with any steward and media host. Recheck whether an old replay, link or cached copy still displays. At shift end, hand over scheduled items, decisions due, open rights checks and emergency contacts for the actual publication channels.\n\nCheck what a visitor can see after the decision. Give the next editor the latest version, outstanding correction and any partner contact who needs the same update.","captureNotes":"Run a simulated withdrawal and create a shift handoff with the affected locations. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A story is removed from Sandy but the linked replay remains public at the provider. What should you do?","choices":[{"id":"a","text":"Assume unpublishing Sandy also removes the external replay."},{"id":"b","text":"Restore the Sandy story so both channels match."},{"id":"c","text":"Contact the channel operator, check access there and follow up with any partner steward."}],"correct_choice_id":"c","explanation":"A linked publication has separate controls on each service.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What does a constructive outgoing editor handoff contain?","choices":[{"id":"a","text":"Active and scheduled records, unresolved risks, decisions and the next responsible officer."},{"id":"b","text":"One file with shared passwords and raw submissions."},{"id":"c","text":"Only last month’s public headlines."}],"correct_choice_id":"a","explanation":"A safe handoff keeps responsibility and actionable references clear.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-island-news-editor' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Choose an activity with a guardian, agree supervision and pickup, and make it easy to ask for help or control sharing.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose a session together","body":"Sandy Sports is forming and its youth activities need a confirmed lead and safeguarding arrangements. The young person and guardian can use the public programme to identify a suitable session, then confirm participation, supervision, medical or access needs and who is authorised to collect the participant. Use My Membership’s family area when the appropriate access is available.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Use fictional family details and only public proposed session pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Know what to do during and after the activity","body":"Tell the lead if you need help or a break, do not know how to use equipment or are unsure who should collect you. Ask the guardian and lead about future sessions and what sharing, results or group messages were approved.\n\nAgree who the junior participant can approach during the activity and who a guardian contacts later to correct an arrangement or change a sharing choice.","captureNotes":"Walk through Programme and event lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-junior-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Rehearse and operate a Sandy broadcast from a confirmed run sheet to the actual viewer and a complete meeting recording handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Build the run sheet and crew roster","body":"Sandy Sports uses Island News and Live for public stream listings. Start with the event lead or Secretary and a confirmed meeting or event. The crew needs the audience, date, venue, approval, producer, encoder and host, an outside viewer check and a way to record locally. For a Rule 4B meeting, use the club workflow for continuous video and audio and the Secretary’s archive handover.\n\nConfirm whether this is a Sandy Rule 4B meeting or a separately authorised event. For a meeting, the Secretary coordinates capture or delegates to the Assistant Secretary, and the Film Club crew may operate. The Schedule 1 Members and publishing group approves a public stream. Name the producer, camera and audio operators, authorised publishing officer and outside-feed checker. Write the opening and closing cues and the continuous local video-and-audio backup plan. Confirm the notice discloses the recording and public stream. Plan for loss of the uplink and any audience or safety issues before opening. For a general meeting streamed to members, check the member-only host access.\n\nOpen Sandy’s meeting recording and archive workflow | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","captureNotes":"Show a fake run sheet with one public meeting and one members-only general meeting. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which role checks that the outgoing sound is actually reaching a viewer?","choices":[{"id":"a","text":"The room announcer listening to the PA."},{"id":"b","text":"The assigned outside-feed checker using the actual viewing URL."},{"id":"c","text":"The camera operator looking only at their viewfinder."}],"correct_choice_id":"b","explanation":"A check at the viewer end catches sound problems that occur after room and encoder mixing.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A Rule 4B public meeting run sheet proposes pausing the master recording for one agenda item. What should the crew do?","choices":[{"id":"a","text":"Build that pause into the scheduled meeting record."},{"id":"b","text":"Use camera only for the difficult item."},{"id":"c","text":"Ask the Secretary and Chair to resolve the agenda before opening and plan continuous video and audio through the formal meeting."}],"correct_choice_id":"c","explanation":"Rule 4B calls for opening-to-close recording. Resolve the problem with the meeting officers before it opens.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[5]', json('{"title":"Return gear and transfer records","body":"Return gear with accessories and fault notes. Hand the Secretary the complete video and audio, backup file check, timing or incident log and the agreed archive and replay references. Send the whole recording through club-controlled transfer. Keep approved original recordings and transcripts intact for the permanent archive, and arrange club-controlled transcription and caption work with the Secretary. If the upload or public replay has gaps, identify them explicitly and hand over the independent source. Escalate any lost recording, unintended exposure or broken member-only access. Assign every unresolved item to a named role with a follow-up date.\n\nGive the Secretary and publishing officer the verified local recording, actual public replay and any gap or outstanding correction they need to resolve.","captureNotes":"Show a fictional kit return and the full file manifest to the Secretary, including the condition of the original and backup. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A network outage is visible on the public player but the complete local recording survived. What should you hand over?","choices":[{"id":"a","text":"Give the Secretary only the host’s incomplete copy."},{"id":"b","text":"Hide the outage by replacing the archive with highlights."},{"id":"c","text":"Give the Secretary the complete local master and outage note and use the complete file for the verified public replay."}],"correct_choice_id":"c","explanation":"The independent local master can supply the full record and replay. The record of the outage explains what viewers saw live.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You discover that a member-only archive link works when copied into a signed-out browser. What should you do?","choices":[{"id":"a","text":"Report it to the Secretary and media host operator, correct hosting access and retest."},{"id":"b","text":"Leave it because the original index is protected."},{"id":"c","text":"Put the same link on Island News to make it easier to find."}],"correct_choice_id":"a","explanation":"The underlying host must enforce member access independently of the archive index.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-live-broadcast-crew' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Judge whether a Sandy Sports visit or remote contribution is workable, and agree a realistic next step with the lead.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find a suitable activity","body":"Check the Sandy Sports public programme for an actual activity. Ask which parts of the proposal are confirmed, then confirm travel, venue, fees, weather updates and an organiser to call. If travel is impractical, ask which genuine remote tasks or later dates are open.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture the public places and programme pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Handle changes and keep in contact","body":"Find the route for cancellation, substitution, equipment return and feedback. Keep your account and contact preferences current if you are using an authorised member route. Work with the organiser before sharing any assumed date or member benefit.\n\nAgree when to reconfirm before travelling or where to deliver your remote contribution. Tell the organiser early if a connection or travel change affects the arrangement.","captureNotes":"Walk through Activity contact and My Membership with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-non-resident-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Take chair responsibility for a formation meeting, scope a real decision and keep the oversight and handover trail clear.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Establish formation status and authority","body":"Sandy Sports is a developing club. Confirm the President’s current authority, the actual meeting status and the rules that apply with the Secretary. Use the meeting desk to coordinate agenda, declarations and decisions. Confirm what can be decided and what should go to consultation or a later authorised meeting.\n\nStart with the proposal, current operator and actual formation evidence. Check draft rules, likely roles, decision powers and which existing organisation or site owner can agree a commitment. A reserved officer seat and the website’s committee desks support preparation. Record which matters the planning group can agree and which must wait for the proper authority. Use current Fair Trading guidance for incorporation steps and have the responsible person verify any planned filing.\n\nKeep the proposal and authority references, owner and open confirmation steps in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Governance and decisions with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the proposal and authority references, owner and open confirmation steps using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A prospective sponsor asks for a signed commitment from the proposed President. What needs checking?","choices":[{"id":"a","text":"The name on the website’s reserved officer account and whether the sponsor deadline is near."},{"id":"b","text":"Who can lawfully sign now, what the proposal permits and what decision or confirmation is still needed."}],"correct_choice_id":"b","explanation":"The operating record needs the proposal and authority references, owner and open confirmation steps. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the proposal and authority references, owner and open confirmation steps"},{"id":"b","text":"a role badge and sponsor request with no evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[6]', json('{"title":"Hand over priorities, decisions and authority","body":"Bring the current formation status, draft rules version, upcoming agenda, decisions and unfinished actions, venue and funds status, confidential routes and communications awaiting approval. Give each gap an owner and review date. Confirm individual access changes with the Webmaster and demonstrate how to verify one decision from source to follow-up. Agree the first-week review and record which responsibilities remain with the operator or other people.\n\nKeep a dated handover with approved and proposed authority, records and named next actions in the authorised record.\n\nSet the next review with the responsible leads and give incoming cover the current authority, important deadlines and decisions it cannot make alone.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include a dated handover with approved and proposed authority, records and named next actions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming chair has the dashboard but can''t find the current rules version. What do you do?","choices":[{"id":"a","text":"Tell them to use any version in the constitution builder until an AGM is held."},{"id":"b","text":"Identify the agreed source and version, assign resolution of the gap and keep the handover follow-up open."}],"correct_choice_id":"b","explanation":"The operating record needs a dated handover with approved and proposed authority, records and named next actions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a dated handover with approved and proposed authority, records and named next actions"},{"id":"b","text":"a sign-in confirmation and an undated list of files"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-president' AND revision=1 AND state='draft' AND edit_version=4 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find an island activity, check how to attend or help and know where to see member updates.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Find the local activities","body":"Use Sandy Sports’ public programme to find a sport, film or community activity in the developing club. Ask for the confirmed place, time, contact and conditions. For a member update or recording, use My Membership once your access is available.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the public programme and activity information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Have a say and manage your details","body":"Offer specific ideas based on local needs, attend agreed discussions and ask how proposals are recorded and decided. Use the approved way to check or correct your contact choices. Ask before sharing other people’s images, messages or membership details.\n\nTo check meeting information, start with the notice. Under Sandy’s draft Rule 4B, committee and general meetings have a permanent member recording archive. Open My Membership, Notices & newsletters, then Meeting archive. Public meeting replays also have a public route through Island News and Live.\n\nIf you attended, ask where to give feedback or propose a next activity. A report about accessibility, travel or timing can help the lead plan the next one.","captureNotes":"Show the two replay routes with fictional meeting titles and links. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-resident-member' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run the formation and meeting records, notices, nominations and Rule 4B archive from the proper desk and record each decision.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Set up the formation record and authority register","body":"Sandy Sports is in formation. Start by confirming the Secretary’s authority and current working rules. Use the committee meeting desk for an agenda, minutes and archive. Check the status of the actual meeting, nomination and notice requirements, and who can handle a member record or confirm a public stream.\n\nIdentify the current operator, rules draft, amendment history, nominated people and available evidence of agreed planning work. Use the documents register to index each source, owner, access class and version. Keep actual source files in authorised storage. Mark which legal or membership clarification is pending and use official Fair Trading guidance to check eventual rules and filing responsibilities. Record dates and owners with the prospective Chair and Treasurer.\n\nKeep the source, version, custody, authority and outstanding review in the authorised record.\n\nOpen Sandy’s meeting recording and archive workflow | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","captureNotes":"Walk through Club documents and register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the source, version, custody, authority and outstanding review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A rules draft is changed in the online builder. What should the Secretary record?","choices":[{"id":"a","text":"Replace all earlier versions and mark the new text adopted."},{"id":"b","text":"Index the dated draft and decision route and keep the prior reference available."}],"correct_choice_id":"b","explanation":"The operating record needs the source, version, custody, authority and outstanding review. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the source, version, custody, authority and outstanding review"},{"id":"b","text":"a link titled current constitution with no evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[7]', json('{"title":"Prepare the Secretary’s handover and unresolved actions","body":"Provide authorised references for rules, minutes, decisions, formal checkpoints, membership, message queue and controlled documents. Give the next person a schedule for the next notice, nominations, any filing, event and private requests. Mark what needs authority, what the Assistant Secretary can cover and what is limited to other roles. Verify access and agree a first-week review of missing evidence and due dates.\n\nKeep the current records index, cover and deadlines with restricted references in the authorised record.\n\nPass on the rules edition and the next deadlines, then verify the archive and access with the incoming officer. Each open matter needs a named owner and next action.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the current records index, cover and deadlines with restricted references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A member correction is overdue but belongs in a protected desk. What do you hand over?","choices":[{"id":"a","text":"The authorised record reference, owner, deadline and private access or escalation route."},{"id":"b","text":"A copy of the corrected personal record in a general handover email."}],"correct_choice_id":"a","explanation":"The operating record needs the current records index, cover and deadlines with restricted references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a download of all files without access scope or priorities"},{"id":"b","text":"the current records index, cover and deadlines with restricted references"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-secretary' AND revision=1 AND state='draft' AND edit_version=4 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find confirmed Sandy Sports activities and follow an idea, volunteer offer or question to the right place.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Tour the proposed programme","body":"Sandy Sports is a developing club proposal for sport, film and community activity on Minjerribah. Use the public site to compare programme ideas, places and participation routes. Look for a confirmed date, venue and contact before making a commitment. Use How it works to find the relevant route.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture the public programme and places pages. Use visual labels for proposed and confirmed information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Know which person to ask","body":"Use the organiser for activity timing, the project contact for founding or support, and the proper private route for a membership or access question. Ask for current confirmation of any booking or proposed event before travelling.\n\nUse the programme, enquiry route or How it works page to take one specific next step. If an item is a proposal, ask what decision or permission would let it move forward.","captureNotes":"Walk through Join, My Membership and public contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-site-tour' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Build a workable sport pathway around a real session, accessible participation, safeguarding and a roster someone can run.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Define the sport pathway and people it serves","body":"Sandy Sports is forming. Start with a particular sport, intended participants, responsible organiser and confirmed site. Use the public programme and current committee plans to check availability. Form the session around format, supervision, equipment, costs and access for beginners. Check who can authorise the activity before asking people to join.\n\nChoose a proposed sport and the skills, audience, purpose and space it needs. Build a sequence from a beginner introduction to further practice, with roles for coaches, officials and volunteers. Check inclusion and accessible options with participants and how the three towns would use the programme. Name who can verify coaching or officiating requirements and confirm what is a concept or an agreed activity.\n\nKeep the audience, skill pathway, coach or official and planned approved dates in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Sports and coaching calendar with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the audience, skill pathway, coach or official and planned approved dates using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A mixed-level session is advertised as beginner-friendly without a beginner plan. What changes?","choices":[{"id":"a","text":"Keep one standard session so no adjustments need to be recorded."},{"id":"b","text":"Define the supported starting activity, coach and accessible adjustments before publication."}],"correct_choice_id":"b","explanation":"The operating record needs the audience, skill pathway, coach or official and planned approved dates. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the audience, skill pathway, coach or official and planned approved dates"},{"id":"b","text":"a list of sport names with no teaching or support roles"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[5]', json('{"title":"Review the programme and hand over","body":"At close confirm equipment return, faults, expenses, volunteer feedback and evidence of what changed. Log attendance or feedback with the agreed level of detail. Bring future coach, venue and budget decisions to the right group. Give the successor the programme version, contacts, duties not covered, unresolved safety or maintenance issues and a review date.\n\nKeep the programme version, outcomes and gear or authority exceptions with successors in the authorised record.\n\nShare where newcomers struggled and what the next lead can change. Record the decision on the next session, check date and safe fallback.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the programme version, outcomes and gear or authority exceptions with successors using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One borrowed item was returned damaged and sessions restart next week. What do you leave?","choices":[{"id":"a","text":"The item and fault, custody record, follow-up owner and decision about next use."},{"id":"b","text":"A note that all items were returned and the programme can continue."}],"correct_choice_id":"a","explanation":"The operating record needs the programme version, outcomes and gear or authority exceptions with successors. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a calendar export with no equipment or owner notes"},{"id":"b","text":"the programme version, outcomes and gear or authority exceptions with successors"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-sport-lead' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Agree a useful offer of time, gear, funds or facilities, along with limits and any acknowledgement.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Choose a practical offer","body":"Sandy Sports is a developing club. A supporter can ask about a specific activity or need through the public site. Check who can accept the offer and who will look after it. Name the item, amount or availability and any conditions. Acknowledgement and publicity need their own agreement with the club.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the public interest and equipment wishes pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Check delivery and follow-up","body":"Keep the agreed reference, date, custody and named contact for deliveries or expenses. Tell the project how to reach you if plans change. Ask what they can report back and how to resolve damaged items or an incorrect public acknowledgement.\n\nAsk the receiving lead to confirm what was delivered and how it will be used. If conditions change, agree a return, revised use or a different contribution.","captureNotes":"Walk through Project and asset contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-supporter' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Set up and operate financial records with accountable approvals, evidence and a clear reporting handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Identify the funds and decision authority","body":"Start with Sandy Sports’ formation status, authorised custodian and actual finance authority. Check whose funds and equipment these are and who can approve, pay or review a commitment. Open the finance desk for a particular cost or receipt and trace it from evidence through reconciliation and the next report.\n\nIdentify the actual operator and whom each offer, invoice or commitment belongs to. Use the confirmed decision and approved private records before referring to funds as club funds. Check who can open or manage accounts, approve spending, release prices or speak to funders. Record starting balances, restrictions and obligations. Keep planning estimates separate. Use individually authorised access and check the responsible records before transferring custody.\n\nKeep the operator, accounts or proposed custody and actual authority references in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Shop, stock and prices with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the operator, accounts or proposed custody and actual authority references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed fundraising budget names a club bank account whose status is unclear. What should be recorded?","choices":[{"id":"a","text":"Treat the cash sheet as a record of money already held by the proposed club."},{"id":"b","text":"Keep the amounts in planning and get the account owner, intended recipient and authority verified first."}],"correct_choice_id":"b","explanation":"The operating record needs the operator, accounts or proposed custody and actual authority references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the operator, accounts or proposed custody and actual authority references"},{"id":"b","text":"an estimated balance without an identified legal holder"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[6]', json('{"title":"Transfer finance and custody","body":"Provide the authorised record locations, reconciled balances, budgets, open costs, grant milestones, supporter terms, equipment custody and finance or storage access. Name who can approve ongoing transactions now, who owns pending applications and who must review later. Verify any access changes and actual transfer of property through the appropriate process. Agree a first-week reconciliation and a check for outstanding approvals.\n\nKeep the current finance index, custody, access and owner for each pending item in the authorised record.\n\nGive the next officer the reconciled position, safe evidence route and dates when decisions or grant conditions need checking.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the current finance index, custody, access and owner for each pending item using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A successor receives a versioned report but cannot find the receipt evidence. How do you close the gap?","choices":[{"id":"a","text":"Treat the report as complete because it has a checked version number."},{"id":"b","text":"Assign the source check to the responsible person and keep the item open until verified."}],"correct_choice_id":"b","explanation":"The operating record needs the current finance index, custody, access and owner for each pending item. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the current finance index, custody, access and owner for each pending item"},{"id":"b","text":"a summary report with no source or secure transfer evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-treasurer' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Cover the chair or coordinate open work with agreed authority, dates and clear escalation.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree deputy cover and access","body":"Start with the proposed Sandy Sports office and an actual cover request. Ask the Chair or organiser to agree the scope and end date. Use the relevant committee desk and decision record to see what the deputy can lead and what still requires another officer or formal decision. Discuss any barrier with the person doing the work.\n\nCheck the prospective role status and what authority has actually been recorded. Agree when you would cover the Chair and which decisions you can facilitate, recommend or refer. Read the actual meeting basis, agenda and possible conflicts before acting. Use your own approved access and check which member or safeguarded records your role can open.\n\nKeep the cover and role status, permitted actions and decision owners in the authorised record.\n\nWhen covering as Chair, confirm the Secretary or Assistant Secretary is running the Rule 4B recording and knows the opening and closing cues. Require continuous video and audio for a committee or general meeting. If a public stream is planned, check the wording of the notice, the publishing officer’s approval and the external viewer confirmation before opening. If connection fails, protect the local capture and arrange an accurate status update with the publishing officer.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Show the deputy taking over a fictional meeting, with the recording and public approval handoff distinguished. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Chair asks you to run a discussion but a commitment is proposed during it. What do you check?","choices":[{"id":"a","text":"Check the scope of your cover and take the commitment through the current authorised decision process."},{"id":"b","text":"Assume the cover includes authority for every item discussed."}],"correct_choice_id":"a","explanation":"The operating record needs the cover and role status, permitted actions and decision owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"As acting Chair, who takes responsibility for the video, audio and transcripts in the Rule 4B archive?","choices":[{"id":"a","text":"The Vice President automatically replaces the Secretary as archive custodian."},{"id":"b","text":"The Film Club operator takes control of the official archive by running the equipment."},{"id":"c","text":"The Secretary, with the delegated Assistant Secretary able to carry out the recording or archive work."}],"correct_choice_id":"c","explanation":"Acting chair cover changes who runs the meeting. The Secretary remains responsible for recording and archiving.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}'),
    '$[6]', json('{"title":"Transfer the deputy’s live work","body":"Prepare the next programme, scope of cover, conflict items, owners, venue and equipment dependencies, private escalation contacts and unresolved partner messages. Record what belongs to the Chair, the individual leads and the prospective deputy. Verify access, return equipment if applicable and agree the date on which the incoming person will review unfinished tasks.\n\nKeep the deputy scope, cross-team dependencies and dated first review in the authorised record.\n\nReturn a short cover record with the decisions made, what changed and which officer owns the next step. Confirm the next date with people affected.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the deputy scope, cross-team dependencies and dated first review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Your successor can see the calendar but two leads are waiting for a decision. What do you transfer?","choices":[{"id":"a","text":"The actual clash and decision owner, responsible contacts and review date."},{"id":"b","text":"The calendar link and a note that leads will contact them if needed."}],"correct_choice_id":"a","explanation":"The operating record needs the deputy scope, cross-team dependencies and dated first review. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a copy of the programme with no accountability"},{"id":"b","text":"the deputy scope, cross-team dependencies and dated first review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-vice-president' AND revision=1 AND state='draft' AND edit_version=4 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find a real task, agree a safe brief and finish with an equipment and next-shift handover.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Ask about a real task","body":"Sandy Sports’ public site explains activities in development. Look for a confirmed session or ask the named organiser if a suitable volunteer task is open. With the lead, agree duties, dates, access, supervision and whether any checks are needed before arrival. My Membership’s Helping out area can be used when access is available.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Capture a fictional run sheet from an agreed demo or paper example. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    '$[4]', json('{"title":"Return gear and leave a usable update","body":"Return equipment and record condition or faults. Pass on any remaining tasks, who owns them and the next check. Confirm who receives any expense or contribution record and give feedback or ask about future activity through the appropriate contact.\n\nTell the organiser what was completed and which task or concern remains. Ask for more training or a different assignment if the role needs support you could not get.","captureNotes":"Walk through Event lead and asset contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-volunteer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Set up individual role access, check what users can actually reach and transfer service control and recovery responsibly.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Inventory systems, status and custodians","body":"Sandy Sports is in formation. Begin with the service owner’s authority and identify the site, accounts, authorised roles and recovery owners. Use the committee access table to plan a role check. Test with controlled accounts so a preview is not mistaken for the real permissions a new member or officer receives.\n\nMap the public site, website provider, repository, database, operator controls, email or media integrations, domain and record owners. Check which features are proposals, synthetic demos, enabled functions and closed formal approvals. Hold or route proposals for new integrations, publishing or paid services to the authorised decision-maker. Record renewal and backup responsibilities with an independent recovery contact.\n\nKeep the service and owner inventory, status, operator and open approval in the authorised record.\n\nOpen Sandy Sports’ process and access map | https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html","captureNotes":"Walk through Webmaster and External connections with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the service and owner inventory, status, operator and open approval using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A useful integration appears in the External connections desk. What makes it ready to enable?","choices":[{"id":"a","text":"A recorded authorised decision, scoped permissions, responsible people and tested safeguards."},{"id":"b","text":"The existence of a completed proposal form in the integration desk."}],"correct_choice_id":"a","explanation":"The operating record needs the service and owner inventory, status, operator and open approval. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a URL list labelled active services"},{"id":"b","text":"the service and owner inventory, status, operator and open approval"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    '$[6]', json('{"title":"Complete the technical handover","body":"Give the incoming operator a dated map of services, deployment records, open issues, access scopes, custody, renewals and test evidence. Have them demonstrate a safe release and where to find recovery material. Verify changes to outgoing access and review the timeline of scheduled work. Identify unresolved tasks and the decision-maker on each. Confirm a first-week session that checks actual authorised access.\n\nKeep the checked provider and recovery access, workflows, due dates and responsible contacts in the authorised record.\n\nShow the responsible officer verified account and archive access, who can restore the service and the next action to finish an incomplete change.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the checked provider and recovery access, workflows, due dates and responsible contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Webmaster can publish but cannot access the approved recovery route. What is the next step?","choices":[{"id":"a","text":"Record and resolve the approved access gap before closing the recovery handover."},{"id":"b","text":"Keep the previous account in use for every emergency."}],"correct_choice_id":"a","explanation":"The operating record needs the checked provider and recovery access, workflows, due dates and responsible contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an administrator password and a list of browser favourites"},{"id":"b","text":"the checked provider and recovery access, workflows, due dates and responsible contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-webmaster' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;
